window.TM_ISSUES = {"policy":[{"title":"산업부, 충청권 메가프로젝트 종합지원방안 발표…삼성전자 HBM 패키징 팹 등 착공","summary":["산업통상부가 삼성전자 HBM 패키징 팹 건설 현장에서 충청권 메가프로젝트 착공식을 열고 '충청권 메가프로젝트 종합지원방안'을 발표했다.","7월 발전비전 보고회 뒤 약 4개월 만에 착공으로 이어졌으며, 투자 규모는 대기업 8개사 6.0조원, 중견·중소 100개사 16.5조원, 외투 4개사 1.1조원이다."],"url":"https://www.motir.go.kr/kor/article/ATCL3f49a5a8c/172400/view","date":"2026-11-12","country":"KR","type":"industrial","type_ko":"산업","source":"산업통상부","as_of":"2026-11-12"},{"title":"비상경제장관회의, 유류세 인하 2개월 연장·'2027년 경제성장전략' 12월 수립","summary":["정부가 11월 말 종료 예정이던 유류세 인하 조치를 2개월 연장하고, 양극화 완화와 잠재성장률 제고를 담은 '2027년 경제성장전략'을 12월 중 마련하기로 했다.","피지컬 AI 핵심 부품인 차세대 센서·액추에이터·휴머노이드용 이차전지 등 초혁신경제 선도 프로젝트 신규 과제를 추진하고, 범정부 양극화 대응 TF를 꾸린다."],"url":"https://www.mofe.go.kr/nw/nes/detailNesDtaView.do?searchBbsId1=MOSFBBS_000000000028&searchNttId1=MOSF_000000000079917&menuNo=4010100","date":"2026-11-11","country":"KR","type":"fiscal","type_ko":"재정","source":"재정경제부","as_of":"2026-11-12"},{"title":"과기정통부·엔비디아 협력…SK텔레콤·리벨리온 NVLink Fusion 협약으로 국산 NPU 연계 추진","summary":["엔비디아·SK텔레콤·리벨리온이 11월 9일 업무협약을 맺고, SK텔레콤 AI 데이터센터에서 엔비디아 NVLink Fusion으로 리벨리온 NPU와 엔비디아 GPU를 연계하는 이기종 컴퓨팅을 추진한다.","과기정통부는 이번 협력을 다른 국산 NPU 기업으로 넓히고 실증·사업화·수출까지 이어지도록 지원하겠다고 밝혔다."],"url":"https://www.msit.go.kr/bbs/view.do?sCode=user&mPid=208&mId=307&bbsSeqNo=94&nttSeqNo=3187936","date":"2026-11-09","country":"KR","type":"industrial","type_ko":"산업","source":"과학기술정보통신부","as_of":"2026-11-12"},{"title":"정부, 증권사 신용융자 담보비율 유지의무 3개월 면제","summary":["정부가 긴급 시장상황점검회의에서 주가 급락에 따른 과도한 반대매매를 막기 위해 증권사의 신용융자 담보비율 유지의무(140%)를 3개월간 면제하기로 했으며, 11월 9일 시행한다.","변동성이 더 커지면 추가 시장안정 조치를 준비하고, 글로벌 반도체 산업과 주요국 정책 동향을 지속 모니터링하기로 했다."],"url":"https://www.fsc.go.kr/no010101/88100","date":"2026-11-06","country":"KR","type":"regulation","type_ko":"규제","source":"금융위원회","as_of":"2026-11-12"},{"title":"대외경제장관회의, 미 중간선거 후 통상·산업 정책 변화 점검","summary":["제276차 대외경제장관회의에서 정부는 미국 중간선거 이후 관세·수출통제 등 행정부의 통상 조치와 의회의 산업 지원 정책 변화가 우리 기업에 미칠 영향을 선제적으로 점검하겠다고 밝혔다.","기존 한미 무역합의를 안정적으로 이행하고 미국 행정부·의회·주정부와 소통을 강화해 조선·에너지 등 전략산업 협력 기회를 발굴하기로 했다."],"url":"https://www.mofe.go.kr/nw/nes/detailNesDtaView.do?searchBbsId1=MOSFBBS_000000000028&searchNttId1=MOSF_000000000079883&menuNo=4010100","date":"2026-11-06","country":"KR","type":"tariff","type_ko":"관세","source":"재정경제부","as_of":"2026-11-12"},{"title":"인민은행, 자사주 매입·지분 확대용 재대출 금리 1%로 인하","summary":["인민은행이 11월 4일부터 주식 자사주 매입·지분 확대용 재대출 금리를 0.25%p 내린 1%로 적용한다고 발표했다.","지원 대상은 전국 은행 21곳과 시스템 중요 도시상업은행 5곳(지원 비율 100%, 만기 1년)이며, 11월 2일 좌담회 이후 은행 신청액이 2,000억위안을 넘었다."],"url":"https://www.pbc.gov.cn/goutongjiaoliu/113456/113469/2026110408502315269/index.html","date":"2026-11-04","country":"CN","type":"monetary","type_ko":"통화","source":"中国人民银行","as_of":"2026-11-12"},{"title":"FOMC, 연방기금금리 3.75~4.00% 동결","summary":["연방공개시장위원회가 연방기금금리 목표 범위를 3.75~4.00%로 유지했으며 표결은 10대 2였다.","쿡·해맥 위원은 0.25%p 인상을 주장하며 반대했고, 성명은 인플레이션이 여전히 높다고 평가했다."],"url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20261028a.htm","date":"2026-10-28","country":"US","type":"monetary","type_ko":"통화","source":"Federal Reserve","as_of":"2026-11-12"},{"title":"한은 금통위, 기준금리 3.00% 유지","summary":["한국은행 금융통화위원회가 기준금리를 3.00%로 유지했으며, 대내외 위험요인의 전개상황과 두 차례 인상의 파급영향을 점검할 필요가 있다고 판단했다.","금년과 내년 성장률은 8월 전망치(3.3%, 2.9%)를 상당폭 상회하고, 내년 소비자물가·근원물가 상승률은 기존 전망치(2.3%, 2.5%)를 웃돌 것으로 예상했다."],"url":"https://www.bok.or.kr/portal/bbs/P0000559/view.do?nttId=11065823&menuNo=200690","date":"2026-10-22","country":"KR","type":"monetary","type_ko":"통화","source":"한국은행","as_of":"2026-11-12"},{"title":"한은 금통위, 기준금리 3.00%로 0.25%p 인상","summary":["한국은행이 기준금리를 2.75%에서 3.00%로 0.25%p 올려, 7월 16일(2.50%→2.75%)에 이어 연속 인상했다.","다음 금통위 통화정책방향 결정은 11월 26일로 예정돼 있다."],"url":"https://www.bok.or.kr/portal/singl/baseRate/list.do?dataSeCd=01&menuNo=200643","date":"2026-08-27","country":"KR","type":"monetary","type_ko":"통화","source":"한국은행","as_of":"2026-11-06"}],"econ":[{"title":"高通CEO谈科技股暴跌：对我们而言“不存在AI板块回调”","title_ko":"퀄컴 CEO \"반도체 업계 웨이퍼·기판·패키징 모두 부족…AI 조정 우리와 무관\"","summary":["퀄컴의 크리스티아누 아몬 CEO는 AI 관련주 급락에 대해 퀄컴은 데이터센터 사업을 막 시작해 'AI 조정'이 해당되지 않는다고 말했다.","그는 반도체 업계가 웨이퍼·기판·패키징 생산능력이 모두 부족할 만큼 수요가 강하고, 에너지 설비 공급 기간이 연산 장비보다 길어 실제 구축 속도와 시장 기대 사이에 차이가 있을 수 있다고 지적했다.","퀄컴은 지난 9월 장기 계약에 따라 아마존이 최대 600억달러어치의 AI 데이터센터 칩과 관련 제품을 살 수 있다고 밝힌 바 있다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-12/doc-iniynyav1640436.shtml","media":"新浪财经","published_local":"2026-11-12 23:05 Shanghai","published_kst":"2026-11-13 00:05 KST","tickers":["QCOM"],"names":["퀄컴"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-12"},{"title":"AI반도체주 일제히 급등…마이크론 시총 하루새 130조원↑","title_ko":"코어위브 깜짝 실적에 美 반도체주 급등…마이크론 11.9%↑·필라델피아반도체지수 5.7%↑","summary":["11일 뉴욕증시에서 코어위브의 시장 예상을 웃돈 3분기 실적을 계기로 필라델피아반도체지수가 5.7% 올랐고, S&P500은 1.31%, 나스닥은 1.60% 상승했다.","마이크론은 11.9% 오른 811.3달러로 시가총액이 하루 새 975억달러 늘었고, 샌디스크(13.7%)·SK하이닉스 ADR(9.7%)도 급등했지만 엔비디아는 2.9% 반등에 그쳤다.","코어위브는 현 금리 수준에서 2027년까지 모회사 무담보채를 추가 발행하지 않고 신규 자금 조달을 50억달러 미만으로 하겠다고 밝혀 주가가 24.7% 뛰었고, 오라클도 8.8% 올랐다."],"url":"https://www.yna.co.kr/view/AKR20261112011400009","media":"연합뉴스","published_local":"2026-11-12 06:50 Seoul","published_kst":"2026-11-12 06:50 KST","tickers":["MU"],"names":["마이크론"],"sectors":["semi_chip"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261112009700072"},{"media":"한국경제","url":"https://www.hankyung.com/article/2026111215046"}],"as_of":"2026-11-11"},{"title":"瑞银：服务器CPU需求持续强劲，Arm市场份额升至20.1%，英特尔降至51.5%","title_ko":"UBS \"3분기 서버 CPU 출하 31%↑\"…Arm 점유율 20.1%로 상승, 인텔 51.5%로 하락","summary":["UBS는 3분기 세계 서버 CPU 출하량이 전 분기보다 약 6%, 전년보다 31% 늘었다고 밝혔다.","출하량 기준 Arm 계열 점유율은 2.5%p 오른 20.1%, 인텔은 2.4%p 내린 51.5%였고 AMD는 28.4%로 비슷했다.","UBS는 메모리 공급 병목으로 2030년 실현 가능한 CPU 시장을 약 2,100억달러로 봤고, 메모리 가격 상승을 반영해 2027년 PC 출하 전망을 2% 증가에서 4% 감소로 낮췄다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-11/doc-iniykqvx2240025.shtml","media":"新浪财经","published_local":"2026-11-11 21:17 Shanghai","published_kst":"2026-11-11 22:17 KST","tickers":["INTC"],"names":["인텔"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-11"},{"title":"모건스탠리 '반도체 저승사자', 삼전닉스 30만9천원·160만원으로 하향","title_ko":"모건스탠리, 삼성전자·SK하이닉스 목표가 19%·38% 하향…\"2028년 메모리 실적 절벽 우려\"","summary":["모건스탠리가 SK하이닉스 목표주가를 260만원에서 160만원으로, 삼성전자는 38만1,000원에서 30만9,000원으로 낮추면서도 내년 영업이익 전망은 각각 13%, 9% 올렸다.","2027년 말부터 신규 공장이 가동돼 공급이 늘고, 미국 중간선거 뒤 약 5GW 데이터센터가 2029년으로 미뤄져 2028년 신규 설비 증가율이 21%에서 9%로 낮아질 것으로 봤다.","투자의견은 두 종목 모두 비중 확대를 유지하고 최선호주를 삼성전기에서 삼성전자로 바꿨으며, 노무라는 공급 부족이 2028년까지 이어진다며 목표가를 유지해 시각이 갈렸다."],"url":"https://www.yna.co.kr/view/AKR20261110080700008","media":"연합뉴스","published_local":"2026-11-10 11:30 Seoul","published_kst":"2026-11-10 11:30 KST","tickers":["005930.KS","000660.KS"],"names":["삼성전자","SK하이닉스"],"sectors":["semi_chip"],"related":[{"media":"매일경제","url":"https://www.mk.co.kr/news/stock/12204249"}],"as_of":"2026-11-10"},{"title":"SoftBank swings to $7 billion loss after U.S. data center hit and Intel share decline","title_ko":"소프트뱅크, 2분기 순손실 1조1,200억엔…미국 AI 데이터센터 발전설비 조달 손실·인텔 주가 하락","summary":["소프트뱅크그룹이 회계연도 2분기에 1조1,200억엔(70억달러) 순손실을 냈다.","미국 AI 데이터센터용 발전설비 조달 계획 변경으로 상반기 5,972억엔 손실을 반영했고, 9월 말까지 발전설비에 낸 누적 대금은 94억8,000만달러다.","OpenAI 누적 투자는 546억달러(공정가치 996억달러)이며, 회사는 새 투자 유치에 따른 기업가치 상승분을 3분기에 반영할 수 있다고 밝혔다."],"url":"https://www.cnbc.com/2026/11/10/softbank-2q-earnings-tech-selloff.html","media":"CNBC","published_local":"2026-11-10 04:01 New_York","published_kst":"2026-11-10 18:01 KST","tickers":["INTC"],"names":["인텔"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-10"},{"title":"IBM将停止为美国咨询部门大部分岗位提供签证和绿卡担保","title_ko":"IBM, 미국 컨설팅 부문 대부분 직무에 비자·영주권 지원 중단","summary":["IBM이 트럼프 행정부의 전문직 취업비자 프로그램 강화에 따라 최대 사업부인 컨설팅 부문의 일부 직무에 대한 이민 보증을 중단한다.","해당 직원은 미국 밖에서 IBM 업무를 계속하거나 연말에 회사를 떠나야 하며, 컨설팅 부문 인력은 15만명이 넘는다.","행정부는 지난달 마이크로소프트·어도비 등 8개사가 미국 취업비자 프로그램을 남용했다며 이용 자격을 정지했다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-10/doc-iniyhmwu9121663.shtml","media":"新浪财经","published_local":"2026-11-10 23:37 Shanghai","published_kst":"2026-11-11 00:37 KST","tickers":["IBM"],"names":["IBM"],"sectors":["ai_sw"],"related":[],"as_of":"2026-11-10"},{"title":"AI 데이터 센터 규제 우려 지속…코스피, 5000선 겨우 사수","title_ko":"코스피 0.81% 내린 5,018.85로 5,000선 사수…삼성SDI 11% 급락","summary":["코스피가 9일 40.84포인트(0.81%) 내린 5,018.85로 마감해 5,000선을 지켰고, 장중에는 기관 저가 매수로 2.24%까지 오르기도 했다.","유가증권시장에서 외국인과 개인은 각각 6,580억원, 5,110억원을 순매도했고 기관만 7,190억원 순매수했다.","삼성전자(+0.64%)와 SK하이닉스(+0.35%)는 올랐지만 LG에너지솔루션(-5.78%)과 삼성SDI(-11.32%)는 내렸고, 코스닥은 0.82% 내린 638.97로 마감했다."],"url":"https://www.hankyung.com/article/2026110952866","media":"한국경제","published_local":"2026-11-09 15:36 Seoul","published_kst":"2026-11-09 15:36 KST","tickers":[],"names":[],"sectors":[],"related":[],"as_of":"2026-11-09"},{"title":"星座能源第三季度利润大超预期，上调全年盈利指引，与亚马逊和谷歌扩大核电合作","title_ko":"컨스텔레이션에너지, 3분기 조정 EPS 5.06달러…아마존·구글과 20년 전력 계약으로 원전 증설","summary":["미국 원전·전력 업체 컨스텔레이션에너지의 3분기 조정 EPS는 5.06달러로 시장 예상(3.89달러)을 웃돌았고, 매출은 45.4% 늘어 95억5,000만달러였다.","아마존과의 20년 690MW 전력 구매 계약으로 캘버트클리프스 원전에 30억달러 넘게, 구글과의 20년 계약으로 11개 원자로에 43억달러 넘게 투자해 약 890MW를 늘린다.","2026년 조정 영업 EPS 전망은 12.50~12.80달러로 높였고, 미 에너지부와 최대 50억달러 대출 보증에 조건부 합의했다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-09/doc-iniycwiw3287269.shtml","media":"新浪财经","published_local":"2026-11-09 20:42 Shanghai","published_kst":"2026-11-09 21:42 KST","tickers":["GOOGL","AMZN"],"names":["알파벳","아마존"],"sectors":["internet"],"related":[],"as_of":"2026-11-09"},{"title":"국내 상장사 소액주주 18개월 새 24%↑…삼성전자 797만명 1위","title_ko":"국내 상장사 소액주주 1년 6개월 새 24% 증가…삼성전자 797만명 1위","summary":["리더스인덱스 조사에서 상장사 1,992곳의 소액주주 수 합계는 2024년 말 6,551만명에서 올해 상반기 말 8,136만명으로 24.2% 늘었다.","소액주주가 늘어난 기업은 601곳에 그쳐 일부 대형주가 증가를 주도했고, 소액주주 보유주식 수는 오히려 10.3% 줄었다.","소액주주는 삼성전자 797만명, SK하이닉스 346만명으로 각각 1·2위이고, 증가율은 LS일렉트릭이 720.3%로 가장 높았다."],"url":"https://www.yna.co.kr/view/AKR20261109118900003","media":"연합뉴스","published_local":"2026-11-10 06:00 Seoul","published_kst":"2026-11-10 06:00 KST","tickers":["005930.KS","000660.KS"],"names":["삼성전자","SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-09"},{"title":"669개종목 연중 최저가·코스피 이틀간 11% 폭락…숫자로 본 증시급락(종합)","title_ko":"코스피 이틀간 10.98% 폭락…삼성전자·SK하이닉스 합산 시총 2천조원 붕괴","summary":["코스피가 6일 6.02% 내린 5,059.69로 마감해 이틀간 10.98% 떨어졌고, 이날 개장 3분여 만에 서킷브레이커가 발동됐다.","삼성전자(-6.35%)와 SK하이닉스(-10.44%)의 합산 시총은 1,930조원으로 6월 25일 고점보다 53.77% 줄었다.","코스피 시총은 4,175조원으로 6월 22일 고점(7,450조원) 대비 43.96% 감소했다."],"url":"https://www.yna.co.kr/view/AKR20261106071651008","media":"연합뉴스","published_local":"2026-11-06 16:52 Seoul","published_kst":"2026-11-06 16:52 KST","tickers":["005930.KS","000660.KS"],"names":["삼성전자","SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-08"},{"title":"[뉴욕증시-주간전망] 美 인플레 향방은…'AI 풍향계' 코어위브 실적 주목","title_ko":"이번 주 뉴욕증시, 10일 미국 CPI와 코어위브 실적이 분수령","summary":["S&P500이 4주 연속 하락하고 나스닥이 고점 대비 10% 조정을 받은 가운데, 이번 주는 10일 나오는 10월 CPI와 장 마감 후 코어위브 3분기 실적이 관건으로 꼽힌다.","시장은 10월 CPI와 근원 CPI가 전월 대비 각각 0.3% 오르고, 13일 발표되는 PPI는 0.4% 오를 것으로 예상한다.","잭스 추정치 기준 코어위브의 3분기 매출은 35억달러(+159%), 주당순손실은 1.17달러다."],"url":"https://www.yna.co.kr/view/AKR20261108006800009","media":"연합뉴스","published_local":"2026-11-08 07:00 Seoul","published_kst":"2026-11-08 07:00 KST","tickers":["CRWV"],"names":["코어위브"],"sectors":["ai_sw"],"related":[],"as_of":"2026-11-08"},{"title":"반도체 지자체, 내년 법인지방소득세 최대 약 12배로 늘 전망","title_ko":"반도체 호황에 경기도 지자체 내년 법인지방소득세 최대 약 12배 전망","summary":["삼성전자·SK하이닉스 실적 호조로 사업장이 있는 경기도 기초지자체의 내년 법인지방소득세 수입이 올해의 최대 약 12배에 이를 전망이다.","삼성전자 납부분은 화성시 1,800억원→1조8천억원, 평택시 1,550억원→1조6천억원, 용인시 635억원→7,400억원으로 추산됐다.","SK하이닉스가 있는 이천시는 7,200억원에서 약 2조원으로 늘 것으로 보이며, 지자체들은 기반시설 투자와 기금 적립에 쓸 계획이다."],"url":"https://www.yna.co.kr/view/AKR20261106129700061","media":"연합뉴스","published_local":"2026-11-07 09:09 Seoul","published_kst":"2026-11-07 09:09 KST","tickers":["005930.KS","000660.KS"],"names":["삼성전자","SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-08"},{"title":"코스피 시총 고점대비 '40%·3천조 이상' 증발…숫자로 본 증시 급락","title_ko":"코스피 개장 3분33초 만에 서킷브레이커…삼성전자·SK하이닉스 합산 시총 2천조원 아래로","summary":["미국 중간선거 이후 데이터센터 규제 우려로 코스피가 장 초반 8% 넘게 떨어져 오전 9시 3분 33초에 서킷브레이커가 발동됐다(올해 11번째).","삼성전자·SK하이닉스 합산 시총은 오전 11시 6분 기준 1,894조원으로, 6월 25일 고점(약 4,174조원)보다 54.63% 줄었다.","외국인은 6거래일 연속 유가증권시장에서 9조7,355억원을 순매도했으며, 올해 누적 순매도는 217조4,574억원이다."],"url":"https://www.yna.co.kr/view/AKR20261106071600008","media":"연합뉴스","published_local":"2026-11-06 11:06 Seoul","published_kst":"2026-11-06 11:06 KST","tickers":["005930.KS","000660.KS"],"names":["삼성전자","SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-06"},{"title":"Nasdaq sell-off batters Asian chip stocks as SK Hynix, Samsung, Softbank, TSMC tumble","title_ko":"나스닥 조정 국면 진입에 아시아 반도체주 동반 급락…TSMC -9.6%, 어드밴테스트 -12.2%","summary":["나스닥이 5.5% 급락해 조정 국면에 들어서자 6일 아시아 기술주가 일제히 떨어졌다.","SK하이닉스는 8% 넘게, 삼성전자는 7% 하락했고 대만 TSMC(-9.6%), 일본 어드밴테스트(-12.2%)·소프트뱅크그룹(-11.6%)도 급락했다.","투자자들은 민주당의 중간선거 압승으로 데이터센터 개발 규제가 강화돼 AI 칩·인프라 수요가 둔화할 수 있다고 우려했다."],"url":"https://www.cnbc.com/2026/11/06/tech-stocks-sk-hynix-samsung-softbank.html","media":"CNBC","published_local":"2026-11-05 21:40 New_York","published_kst":"2026-11-06 11:40 KST","tickers":["000660.KS"],"names":["SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-06"},{"title":"앤트로픽 몸값 2천조원 밑도나…AI주 폭락에 11월 상장 먹구름","title_ko":"앤트로픽 IPO 목표 기업가치 1.5조달러 달성 불투명…AI주 급락에 회의론","summary":["이달 상장을 추진 중인 앤트로픽이 목표 기업가치 1조5천억달러를 인정받기 어려울 수 있다고 WSJ가 소식통을 인용해 보도했다.","공모 참여를 검토 중인 주요 투자자 3명이 가치 하향 조정이 필요하다고 봤고, 한 명은 1조달러 안팎을 제시했으며 상장 일정이 늦춰질 가능성도 제기됐다.","앞서 오픈AI는 목표 300억달러의 절반에 못 미치는 111억달러를 조달했고, 앤트로픽은 연산 인프라 확보를 위해 8,950억달러의 지출 약정을 맺어 둔 상태다."],"url":"https://www.yna.co.kr/view/AKR20261106058600091","media":"연합뉴스","published_local":"2026-11-06 10:42 Seoul","published_kst":"2026-11-06 10:42 KST","tickers":["CSCO"],"names":["시스코"],"sectors":["hardware"],"related":[],"as_of":"2026-11-06"},{"title":"삼전닉스, 美데이터센터 규제 우려에 7∼9%대 급락 마감(종합)","title_ko":"美 '블루웨이브' 후 AI 데이터센터 규제 우려…삼성전자·SK하이닉스 7~9%대 급락","summary":["미국 민주당의 중간선거 압승 이후 AI 데이터센터 건설 규제 강화 우려가 커지며 삼성전자(-7.57%)와 SK하이닉스(-9.46%)가 급락 마감했다.","전날 뉴욕증시 3대 지수는 올랐지만 필라델피아 반도체지수는 3.13% 내렸고, 선거와 함께 치러진 지역 주민투표에서도 데이터센터 개발 반대·유예 여론이 압도적이었다.","이날 외국인은 코스피에서 3조4,242억원을 순매도했으며, SK하이닉스(1조5,427억원)와 삼성전자(1조1,687억원)가 순매도 1·2위였다."],"url":"https://www.yna.co.kr/view/AKR20261105040851008","media":"연합뉴스","published_local":"2026-11-05 15:58 Seoul","published_kst":"2026-11-05 15:58 KST","tickers":["005930.KS","000660.KS"],"names":["삼성전자","SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-05"},{"title":"China blocks SoftBank’s US$5.4 billion takeover of ABB’s robotics division","title_ko":"中, 소프트뱅크의 ABB 로봇사업 54억달러 인수 불허","summary":["중국 국가 계획 당국이 소프트뱅크에 ABB 로봇 부문 54억달러 인수를 허용하지 않겠다고 통보했다고 ABB가 밝혔다.","올해 메타에 AI 스타트업 마누스 인수(20억달러 이상)를 되돌리라고 명령한 데 이은 두 번째 대형 거래 불허로, 첨단기술 스타트업에 대한 외국인 투자 심사가 강화되는 흐름이다.","이번 결정으로 손정의 회장이 AI 투자 전략의 핵심으로 내세운 로봇 사업 확장에도 제동이 걸렸다."],"url":"https://www.scmp.com/business/china-business/article/3373415/china-blocks-softbanks-us54-billion-takeover-abbs-robotics-division","media":"SCMP","published_local":"2026-11-05 18:23 Hong_Kong","published_kst":"2026-11-05 19:23 KST","tickers":["META"],"names":["메타"],"sectors":["internet"],"related":[],"as_of":"2026-11-05"},{"title":"苹果一年多来首次发债 拟筹资约70亿美元","title_ko":"애플, 1년여 만에 회사채 발행…약 70억달러 조달 추진","summary":["애플이 1년여 만에 처음으로 투자등급 회사채를 발행해 약 70억달러를 조달할 계획이라고 신랑재경이 소식통을 인용해 보도했다.","만기 2~10년 7개 트랜치로 자금은 자사주 매입·배당·설비투자 등에 쓰이며, 지난주 이후 MS·오라클·메타가 미국에서 합계 500억달러를 조달했다.","2036년 만기물의 논의 금리는 국채 대비 +80bp로, MS(최고 95bp)·메타(185bp)·오라클(330bp)의 초기 가이던스보다 낮다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-06/doc-inixthpq9242380.shtml","media":"新浪财经","published_local":"2026-11-06 00:38 Shanghai","published_kst":"2026-11-06 01:38 KST","tickers":["AAPL"],"names":["애플"],"sectors":["hardware"],"related":[],"as_of":"2026-11-05"}],"stock":[{"rank":1,"title":"시스코(CSCO): 8-K - Current report","title_ko":"시스코, 1분기 매출 185억달러 24%↑ 15년 만의 최고 성장…연간 가이던스 상향","summary":["시스코의 회계연도 1분기 매출은 185억달러로 24% 늘었고, 비GAAP EPS는 1.40달러로 40% 증가해 15년여 만에 가장 높은 성장률을 기록했다.","하이퍼스케일러 대상 AI 인프라 매출 기대치를 2027 회계연도 90억달러로 올렸는데, 이는 2026 회계연도의 두 배가 넘는 규모다.","2분기 매출 전망은 180억~182억달러, 연간 매출 전망은 748억~758억달러로 높였으며, 척 로빈스 CEO는 다년간의 네트워킹 슈퍼사이클 초기라고 밝혔다."],"url":"https://www.sec.gov/Archives/edgar/data/858877/000085887726000170/0000858877-26-000170-index.htm","media":"SEC EDGAR","published_local":"2026-11-12 16:06 New_York","published_kst":"2026-11-13 06:06 KST","tickers":["CSCO"],"names":["시스코"],"sectors":["hardware"],"related":[{"media":"CNBC","url":"https://www.cnbc.com/2026/11/12/cisco-csco-q1-2027-earnings.html"},{"media":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-11-12/cisco-raises-sales-guidance-in-sign-of-ai-fueled-momentum"},{"media":"Bloomberg","url":"https://www.bloomberg.com/news/videos/2026-11-12/cisco-raises-forecast-as-ai-fuels-networking-demand-video"}],"as_of":"2026-11-12"},{"rank":2,"title":"어플라이드머티어리얼즈(AMAT): 8-K - Current report","title_ko":"어플라이드머티리얼즈, 4분기 매출 104억1,000만달러 53%↑ 사상 최대…연간 매출 344억5,000만달러","summary":["어플라이드머티리얼즈의 회계연도 4분기 매출은 104억1,000만달러로 53% 늘어 분기 최대였고, 비GAAP EPS는 4.16달러로 92% 증가했다.","비GAAP 매출총이익률은 50.6%로 2.5%p 높아졌고, 분기 잉여현금흐름은 사상 최대인 26억달러, 주주환원은 24억달러를 넘었다.","연간 매출은 344억5,000만달러로 21% 늘었으며, 개리 디커슨 CEO는 반도체 시스템 사업이 2026년에 40% 넘게 성장할 것이라고 밝혔다."],"url":"https://www.sec.gov/Archives/edgar/data/6951/000162828026073360/0001628280-26-073360-index.htm","media":"SEC EDGAR","published_local":"2026-11-12 16:02 New_York","published_kst":"2026-11-13 06:02 KST","tickers":["AMAT"],"names":["어플라이드머티어리얼즈"],"sectors":["semi_equip"],"related":[],"as_of":"2026-11-12"},{"rank":3,"title":"NAVER IR - 연결재무제표기준영업(잠정)실적(공정공시)","title_ko":"네이버, 3분기 매출 3조4,724억원 분기 최대·영업익 20.9%↓…AI 팩토리 2조원 공급계약","summary":["네이버의 3분기 연결 매출은 3조4,724억원으로 10.7% 늘어 분기 최대였지만, 영업이익은 4,513억원으로 20.9%, 순이익은 4,025억원으로 45.2% 줄었다.","AI 인프라·콘텐츠 투자가 늘었고, 미국 AI 추론 기업과 약 2조원 규모의 AI 팩토리 컴퓨팅 서비스 공급 계약을 맺어 첫 고객을 확보했다.","AI 팩토리 매출은 내년 상반기부터 반영될 예정이며, 1단계 목표 200MW 중 남은 약 180MW를 놓고 10곳 넘는 기업과 추가 계약을 논의하고 있다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261112800027","media":"DART","published_local":"2026-11-12 08:05 Seoul","published_kst":"2026-11-12 08:05 KST","tickers":["035420.KS"],"names":["NAVER"],"sectors":["internet"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261112025452527"},{"media":"DART","url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261112800028"},{"media":"한국경제","url":"https://www.hankyung.com/article/202611122906i"}],"as_of":"2026-11-12"},{"rank":4,"title":"DB하이텍 - 연결재무제표기준영업(잠정)실적(공정공시)","title_ko":"DB하이텍, 3분기 영업이익 900억원 7%↑…전력반도체 수요로 가동률 사실상 100%","summary":["DB하이텍의 3분기 매출은 4,034억원, 영업이익은 900억원으로 각각 14%, 7% 늘었고 영업이익률은 22%였다.","주력 전력반도체 수요가 이어져 공장 가동률이 사실상 100%였고, 고전압 전력반도체 비중 확대로 판매단가도 올랐다.","3분기 누적 매출·영업이익은 1조1,774억원·2,622억원으로 19%·24% 늘었으며, 음성 상우캠퍼스 클린룸을 완공해 월 4만장 생산능력을 더할 계획이다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261112800091","media":"DART","published_local":"2026-11-12 08:32 Seoul","published_kst":"2026-11-12 08:32 KST","tickers":["000990.KS"],"names":["DB하이텍"],"sectors":["semi_chip"],"related":[{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12206280"},{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12206623"},{"media":"한국경제","url":"https://www.hankyung.com/article/2026111219086"}],"as_of":"2026-11-12"},{"rank":5,"title":"에노빅스(ENVX): 8-K - Current report","title_ko":"에노빅스, 3분기 매출 1,100만달러 38%↑…2027년 매출 가이던스 6,500만~8,500만달러 제시","summary":["실리콘 음극 배터리 업체 에노빅스의 3분기 매출은 1,100만달러로 전년보다 38%, 전 분기보다 22% 늘어 6분기 연속 증가했다.","스마트 안경과 드론·방산 매출 비중이 커지면서 비GAAP 매출총이익률은 사상 최고인 34.5%로 13.5%p 높아졌고, 비GAAP 주당순손실은 0.15달러였다.","2027년 매출 가이던스로 6,500만~8,500만달러를 처음 제시했고, 2030년 만기 전환사채 1억2,800만달러를 36% 할인해 상환했으며 구조조정으로 연간 비용을 850만달러 줄인다."],"url":"https://www.sec.gov/Archives/edgar/data/1828318/000182831826000069/0001828318-26-000069-index.htm","media":"SEC EDGAR","published_local":"2026-11-12 07:44 New_York","published_kst":"2026-11-12 21:44 KST","tickers":["ENVX"],"names":["에노빅스"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-12"},{"rank":6,"title":"Nvidia: Ex-prosecutor Joon Kim and Wachtell, Lipton bring big track record to investigation","title_ko":"엔비디아 젠슨 황 CEO 사임…콜렛 크레스 CFO가 임시 CEO 겸임","summary":["엔비디아 이사회는 젠슨 황이 총괄사장·CEO·이사직에서 사임했으며 즉시 효력이 발생한다고 발표했다.","콜렛 크레스 CFO가 정식 후임이 정해질 때까지 임시 CEO를 겸임하고, 이사회는 내부·외부 후보를 모두 놓고 상임 CEO 선임 절차에 들어갔다.","CNBC에 따르면 황은 엔비디아 임원과의 또 다른 불륜 보도 직후 물러났고, 회사가 선임한 와크텔 소속 전직 검사 준 김의 조사 범위가 넓어질 수 있다."],"url":"https://www.cnbc.com/2026/11/12/nvidia-jensen-huang-joon-kim-wachtell-china-spy.html","media":"CNBC","published_local":"2026-11-12 14:58 New_York","published_kst":"2026-11-13 04:58 KST","tickers":["NVDA"],"names":["엔비디아"],"sectors":["semi_chip"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-13/doc-iniypqyi1011235.shtml"},{"media":"WSJ","url":"https://www.wsj.com/finance/stocks/nvidia-tumbles-as-its-ceo-jensen-huang-departs-amid-multiplying-scandals-d380df1f"},{"media":"WSJ","url":"https://www.wsj.com/tech/colette-kress-nvidia-interim-ceo-ff26ef3a"},{"media":"SCMP","url":"https://www.scmp.com/tech/article/3374235/if-jensen-huang-exits-nvidia-who-could-take-us4tr-chipmakers-reins"},{"media":"Bloomberg","url":"https://www.bloomberg.com/news/videos/2026-11-12/nvidia-can-weather-huang-s-departure-ross-gerber-says"},{"media":"매일경제","url":"https://www.mk.co.kr/news/world/12206389"},{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-12/doc-iniynyav1650404.shtml"},{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-13/doc-iniypeku8314711.shtml"},{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-13/doc-iniypksm1116631.shtml"},{"media":"한국경제","url":"https://www.hankyung.com/article/202611123926i"}],"as_of":"2026-11-12"},{"rank":7,"title":"JD-SW: INSIDE INFORMATION - COMPLETION OF VOLUNTARY PUBLIC TAKEOVER OFFER FOR CECONOMY AG","title_ko":"JD닷컴, 독일 세코노미 공개매수 완료…지분 59.8% 13억3,500만유로에 인수해 자회사 편입","summary":["JD닷컴이 유럽 가전 유통사 세코노미에 대한 자발적 공개매수를 마치고 지분·의결권 59.8%를 총 13억3,500만유로에 사들였다.","공개매수 가격은 주당 4.60유로 현금이며, 세코노미는 자회사가 돼 11월 12일부터 JD닷컴 연결 재무제표에 들어간다.","JD닷컴은 세코노미와 함께 유럽의 차세대 유통 플랫폼을 만들겠다고 밝혔다."],"url":"https://www1.hkexnews.hk/listedco/listconews/sehk/2026/1112/2026111201308.pdf","media":"HKEXnews","published_local":"2026-11-12 20:01 Hong_Kong","published_kst":"2026-11-12 21:01 KST","tickers":["9618.HK"],"names":["징둥닷컴"],"sectors":["internet"],"related":[],"as_of":"2026-11-12"},{"rank":8,"title":"SpaceX与特斯拉合并谈判取得进展，最早12月宣布交易","title_ko":"스페이스X·테슬라 합병 협상 진전…이르면 12월 발표 가능","summary":["스페이스X와 테슬라의 합병 협상이 진전돼 이르면 12월에 거래를 발표할 수 있으나, 2027년 초로 늦춰질 수도 있다고 소식통들이 전했다.","양사 이사회와 자문사는 합병 조건과 거래 후 지배구조를 협의 중이며, 스페이스X 시가총액은 1조9,000억달러, 테슬라는 약 1조5,000억달러다.","교환비율 결정과 국가안보 심사, 규제·주주 승인이 남아 있고, 테슬라는 12월 3일 정기 주총을 연다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-13/doc-iniypksr1495342.shtml","media":"新浪财经","published_local":"2026-11-13 04:20 Shanghai","published_kst":"2026-11-13 05:20 KST","tickers":["TSLA"],"names":["테슬라"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-12"},{"rank":9,"title":"메타(META): 8-K - Current report","title_ko":"메타, 6개 만기 유로화 선순위채 발행 완료…최장 2065년 만기","summary":["메타가 11월 12일 6개 만기의 유로화 선순위채 발행을 마쳤다.","2031년물 17억5,000만유로(4.300%), 2033년물 12억5,000만유로(4.650%), 2035년물 10억유로(4.900%)를 발행했다.","2038년물 17억5,000만유로(5.400%), 2044년물 17억5,000만유로(6.050%), 2065년물 15억유로(6.400%)도 함께 발행했고, 주관사는 씨티그룹과 모건스탠리다."],"url":"https://www.sec.gov/Archives/edgar/data/1326801/000119312526458525/0001193125-26-458525-index.htm","media":"SEC EDGAR","published_local":"2026-11-12 16:27 New_York","published_kst":"2026-11-13 06:27 KST","tickers":["META"],"names":["메타"],"sectors":["internet"],"related":[],"as_of":"2026-11-12"},{"rank":10,"title":"LG이노텍, 3분기 누적 애플 매출 14조원…작년보다 25%↑","title_ko":"LG이노텍, 3분기 누적 최대 고객 매출 14조94억원…매출 비중 80.4%","summary":["LG이노텍의 3분기 누적 단일 고객(광학·패키지 사업) 매출이 14조94억원으로 역대 최대였고, 이 고객은 애플로 추정된다.","전체 매출에서 이 고객의 비중은 1년 만에 78.7%에서 80.4%로 1.7%p 커졌다.","상반기 카메라 모듈 수요와 하반기 아이폰18 시리즈·듀오 출시가 영향을 줬고, 이미지센서·CCL/PP·IC 평균 가격은 각각 4.1%, 13.7%, 16.8% 올랐다."],"url":"https://www.yna.co.kr/view/AKR20261112131300003","media":"연합뉴스","published_local":"2026-11-12 15:19 Seoul","published_kst":"2026-11-12 15:19 KST","tickers":["AAPL","011070.KS"],"names":["애플","LG이노텍"],"sectors":["hardware"],"related":[],"as_of":"2026-11-12"},{"rank":11,"title":"삼성 AI 안경 베일 벗었다…12월 10일 국내 출시·65만원부터","title_ko":"삼성전자, AI 안경 30종 공개…12월 10일 한·미 출시, 국내 65만~70만원","summary":["삼성전자가 구글·젠틀몬스터·워비파커와 협업한 AI 안경 '인텔리전트 아이웨어' 30종을 공개하고 12월 10일 한국과 미국에 출시한다.","구글 제미나이로 번역·길 안내·회의 자료 요약을 지원하며, 약 41g 프레임에 1,200만 화소 카메라와 스피커·마이크를 넣었다.","국내에는 젠틀몬스터 컬렉션만 내놓고 가격은 65만~70만원이며, 두 브랜드 온라인 채널에서 사전 판매를 시작했다."],"url":"https://www.yna.co.kr/view/AKR20261112140300017","media":"연합뉴스","published_local":"2026-11-12 23:00 Seoul","published_kst":"2026-11-12 23:00 KST","tickers":["005930.KS","GOOGL"],"names":["삼성전자","알파벳"],"sectors":["internet","semi_chip"],"related":[{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12206741"}],"as_of":"2026-11-12"},{"rank":1,"title":"日本批准亚马逊日本公司整改方案 不再设置价格强制条款 将优化商品检索","title_ko":"일본 공정위, 아마존재팬 시정안 승인…'최저가 강제' 조건 폐지","summary":["일본 공정거래위원회가 판매자에게 타 쇼핑몰보다 낮거나 같은 가격을 요구한 아마존재팬의 시정안을 승인했다.","아마존재팬은 이 가격 조건을 충족해야 장바구니 추천 자리(Buy Box)를 주던 방식을 없애고, 최저가 상품이 검색에서 우선 노출되도록 개선한다.","자진 시정 절차로 위법 판정은 피했으며, 아마존은 미국에서 FTC와 10여개 주 검찰총장이 제기한 유사한 반독점 소송을 진행 중이다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-11/doc-iniykqvx2284840.shtml","media":"新浪财经","published_local":"2026-11-11 22:39 Shanghai","published_kst":"2026-11-11 23:39 KST","tickers":["AMZN"],"names":["아마존"],"sectors":["internet"],"related":[],"as_of":"2026-11-11"},{"rank":2,"title":"\"GPT 아스트라보다 고성능\"…구글 '제미나이4 카본' 공개","title_ko":"구글, 신형 AI 모델 '제미나이4 카본' 출시…API 가격은 GPT-6 아스트라의 40%","summary":["구글이 10일 신형 AI 모델 '제미나이4 카본'을 출시했고, 아티피셜애널리시스 종합 지능지수에서 60점을 받아 오픈AI의 GPT-6 아스트라(57점)를 앞섰다.","실제 업무 657건의 성공률을 재는 오토메이션벤치1.0에서는 53.9%로 아스트라(41.4%)보다 높았고, 선두는 앤트로픽의 '클로드 페이블 5.2'(65점)다.","API 가격은 100만 토큰당 입력 4달러·출력 20달러로 아스트라의 40% 수준이며, 월 100달러 이상인 '구글 AI 울트라' 요금제에서 쓸 수 있다."],"url":"https://www.hankyung.com/article/2026111109451","media":"한국경제","published_local":"2026-11-11 17:32 Seoul","published_kst":"2026-11-11 17:32 KST","tickers":["GOOGL"],"names":["알파벳"],"sectors":["internet"],"related":[],"as_of":"2026-11-11"},{"rank":3,"title":"Meta基础设施主管兼工程联席主管将于2027年离职","title_ko":"메타 인프라 총괄 산토시 자나르단 2027년 초 퇴임…후임에 AWS 출신 데이브 브라운","summary":["메타의 인프라 총괄이자 엔지니어링 공동 책임자인 산토시 자나르단이 인프라 부문 책임자에서 물러나 2027년 초 회사를 떠난다고 직원들에게 밝혔다.","2009년 입사한 그는 메타의 소프트웨어·하드웨어·네트워크·데이터센터와 자체 칩 프로젝트를 이끌었고, 올해 1월부터 연산 자원 전략 조직 'Meta Compute'의 공동 책임자도 맡았다.","후임 인프라 총괄은 AWS에서 약 20년 일한 데이브 브라운 인프라 부사장이며, 자나르단은 인수인계를 위해 1분기 말까지 남는다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-12/doc-iniykzmu8860543.shtml","media":"新浪财经","published_local":"2026-11-12 02:08 Shanghai","published_kst":"2026-11-12 03:08 KST","tickers":["META"],"names":["메타"],"sectors":["internet"],"related":[],"as_of":"2026-11-11"},{"rank":4,"title":"Microsoft Vows to Pay Its Own Way to Power Data Centers","title_ko":"마이크로소프트 \"데이터센터 전력 비용 스스로 부담\"…보조금·요금 전가 없이 조달","summary":["마이크로소프트가 데이터센터 전력을 정부 보조금에 기대지 않고 스스로 비용을 대며 확보하겠다고 밝혔다.","블룸버그에 따르면 회사는 다른 전기 소비자의 요금을 올리지 않는 방식으로 데이터센터 전력을 구할 방안을 찾고 있다.","닛케이아시아는 마이크로소프트가 기술기업들이 AI 데이터센터가 지역에 이익이 된다는 점을 입증해야 한다고 말했다고 전했다."],"url":"https://www.bloomberg.com/news/articles/2026-11-11/microsoft-vows-to-pay-its-own-way-to-power-data-centers","media":"Bloomberg","published_local":"2026-11-11 15:33 New_York","published_kst":"2026-11-12 05:33 KST","tickers":["MSFT"],"names":["마이크로소프트"],"sectors":["ai_sw"],"related":[{"media":"Nikkei Asia","url":"https://asia.nikkei.com/spotlight/global-management-dialogue/global-management-dialogue-2026/microsoft-says-tech-firms-must-prove-ai-data-centers-benefit-locals"}],"as_of":"2026-11-11"},{"rank":1,"title":"크래프톤 IR - 연결재무제표기준영업(잠정)실적(공정공시)","title_ko":"크래프톤, 3분기 매출 9,714억원 역대 최대…영업이익 2,250억원 35.5%↓·순손실 전환","summary":["크래프톤의 3분기 연결 매출은 9,714억원으로 11.6% 늘어 분기 최대였지만, 영업이익은 2,250억원으로 35.5% 줄었고 684억원 순손실로 돌아섰다.","PC 매출이 2,389억원으로 32.5% 줄었는데, 지난해 3분기 대형 컬래버 업데이트가 올해는 4분기에 몰린 탓이며, ADK그룹 인수로 영업비용은 7,464억원으로 43% 늘었다.","3분기 누적 매출은 3조6,330억원(+51%), 영업이익은 1조1,975억원(+14%)이고, 회사는 데드넷 등 신작 5종의 내년 출시와 연간 두 자릿수 성장을 예상했다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261110800492","media":"DART","published_local":"2026-11-10 15:42 Seoul","published_kst":"2026-11-10 15:42 KST","tickers":["259960.KS"],"names":["크래프톤"],"sectors":["internet"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261110134152527"},{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261110134151527"},{"media":"한국경제","url":"https://www.hankyung.com/article/2026111188576"}],"as_of":"2026-11-10"},{"rank":2,"title":"앰프리우스(AMPX): 8-K - Current report","title_ko":"앰프리우스, 3분기 매출 3,910만달러 83%↑ 사상 최대…연간 매출 전망 1억4,500만달러로 상향","summary":["실리콘 음극 배터리 업체 앰프리우스의 3분기 매출은 3,910만달러로 전년 대비 83%, 전 분기 대비 15% 늘어 분기 최대를 기록했다.","매출총이익률은 27%로 전년(15%)보다 높아졌고 순손실은 350만달러로 줄었으며, 미국 매출은 1,220만달러로 전 분기의 2.3배가 됐다.","회사는 2026년 매출 전망을 1억4,500만달러로 올렸고, 새 배터리 SiCore 500을 내놓았으며 2028년 미국 내 증산 계약 대상으로 선정됐다고 밝혔다."],"url":"https://www.sec.gov/Archives/edgar/data/1899287/000189928726000069/0001899287-26-000069-index.htm","media":"SEC EDGAR","published_local":"2026-11-10 16:28 New_York","published_kst":"2026-11-11 06:28 KST","tickers":["AMPX"],"names":["앰프리우스"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-10"},{"rank":3,"title":"엔테그리스(ENTG): 8-K - Current report","title_ko":"엔테그리스, 장기 매출 연평균 15% 성장 목표 제시…5억달러 자사주 매입·배당 10% 인상","summary":["엔테그리스는 자본시장의 날에서 장기 매출 연평균 성장률 목표를 약 15%로 제시했고, 이사회는 5억달러 규모 자사주 매입을 승인했다.","회사는 AI로 반도체 소자 구조가 복잡해지면서 고객의 소재 사용량과 오염 제어 요구가 늘고 있다고 성장 근거를 설명했다.","장기 목표는 조정 매출총이익률 약 55%, 조정 영업이익률 약 35%, 조정 EPS 연평균 약 30% 성장이며, 초과 현금의 약 50%를 환원하고 2027년 1분기부터 분기 배당을 10% 올릴 계획이다."],"url":"https://www.sec.gov/Archives/edgar/data/1101302/000114036126042892/0001140361-26-042892-index.htm","media":"SEC EDGAR","published_local":"2026-11-10 07:31 New_York","published_kst":"2026-11-10 21:31 KST","tickers":["ENTG"],"names":["엔테그리스"],"sectors":["semi_equip"],"related":[],"as_of":"2026-11-10"},{"rank":4,"title":"[단독] 2.5조 실탄채운 LG화학…석화용지에 반도체소재공장 짓는다","title_ko":"LG화학, 여수 범용 석화 용지에 반도체 세정용 IPA 증설 검토…LG엔솔 지분 매각 자금 첫 투입","summary":["LG화학이 여수공장 네오펜틸글리콜(NPG) 공장 용지에 반도체 세정용 이소프로필알코올(IPA) 설비를 늘리는 수천억원 규모 투자를 검토 중이라고 매일경제가 업계를 인용해 보도했다.","NPG는 중국발 공급 과잉으로 수익성이 크게 떨어졌고, IPA는 웨이퍼 불순물 제거용 세정 소재로 삼성전자·SK하이닉스·TSMC 등에 공급된다.","세계 IPA 점유율 1위인 LG화학은 연 16만5,000t을 생산 중이며 수만t을 더 늘릴 계획이고, 지난달 LG에너지솔루션 지분 매각으로 확보한 2조5,000억원이 투입되는 첫 사업이다."],"url":"https://www.mk.co.kr/news/business/12204241","media":"매일경제","published_local":"2026-11-10 17:44 Seoul","published_kst":"2026-11-10 17:44 KST","tickers":["373220.KS","051910.KS"],"names":["LG에너지솔루션","LG화학"],"sectors":["battery_ev"],"related":[{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12204238"},{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12204007"}],"as_of":"2026-11-10"},{"rank":5,"title":"BABA-W: PROPOSED SPIN-OFF AND SEPARATE LISTING OF T-HEAD ON THE MAIN BOARD OF THE STOCK EXCHANGE OF HONG KONG LIMITED","title_ko":"알리바바, 반도체 자회사 T-Head 홍콩 분할 상장 추진…비공개 상장 신청 공시","summary":["알리바바는 데이터센터 칩 자회사 T-Head(핑터우거)를 분할해 홍콩 메인보드에 상장하는 방안을 거래소가 승인해 진행할 수 있게 됐다고 공시했다.","T-Head는 9월 11일 비공개로 상장 신청서(Form A1)를 냈고, 홍콩 공모와 기관 배정으로 H주를 발행하며 상장 뒤에도 알리바바의 자회사로 남는다.","공모 규모·구조와 알리바바의 지분 감소 폭은 정해지지 않았고, 거래소는 기존 주주에게 T-Head 주식 우선 배정을 보장하는 요건의 면제를 허용했다."],"url":"https://www1.hkexnews.hk/listedco/listconews/sehk/2026/1110/2026111001061.pdf","media":"HKEXnews","published_local":"2026-11-10 20:36 Hong_Kong","published_kst":"2026-11-10 21:36 KST","tickers":["9988.HK"],"names":["알리바바"],"sectors":["internet"],"related":[{"media":"SCMP","url":"https://www.scmp.com/business/companies/article/3373974/alibaba-chip-unit-t-head-files-hong-kong-ipo-plan-amid-chinas-ai-self-sufficiency-drive"},{"media":"WSJ","url":"https://www.wsj.com/tech/alibabas-chip-unit-files-for-hong-kong-listing-31f856cb"}],"as_of":"2026-11-10"},{"rank":6,"title":"Nvidia board member Stephen Neal could play big role in probe of CEO Jensen Huang","title_ko":"엔비디아 황 CEO 조사, 이사회가 외부 법률 자문과 주도…FT \"월가 로펌 출신 전직 검사 선임\"","summary":["중국 스파이 의혹 인물과의 불륜을 둘러싼 젠슨 황 CEO 조사는 엔비디아 이사회가 외부 법률 자문의 도움을 받아 이끌고 있다.","CNBC는 쿨리 로펌 CEO 출신으로 수석 사외이사이자 지배구조 책임자인 스티븐 닐의 판단이 조사의 향방을 좌우할 수 있다고 전했다.","파이낸셜타임스는 엔비디아가 이 조사를 이끌 인물로 와크텔 로펌 소속 전직 미국 검사를 선임했다고 보도했다."],"url":"https://www.cnbc.com/2026/11/09/nvidia-jensen-huang-investigation.html","media":"CNBC","published_local":"2026-11-10 15:22 New_York","published_kst":"2026-11-11 05:22 KST","tickers":["NVDA"],"names":["엔비디아"],"sectors":["semi_chip"],"related":[{"media":"Financial Times","url":"https://www.ft.com/content/8d59bf02-960e-4eb1-b5dc-55397e31cea5"},{"media":"WSJ","url":"https://www.wsj.com/tech/ai/how-jensen-huangs-affair-spiraled-into-a-national-security-nightmare-d9b43304"},{"media":"Bloomberg","url":"https://www.bloomberg.com/news/features/2026-11-10/la-crisis-de-nvidia-expone-su-dependencia-de-jensen-huang"},{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12203837"}],"as_of":"2026-11-10"},{"rank":7,"title":"네이버도 마케팅비 절반으로 줄인다","title_ko":"네이버, 마케팅비 최대 절반 감축…1GW AI 팩토리 투자 재원 확보","summary":["네이버가 최근 전 사업 부문에 마케팅 비용 절감을 지시했고, 비용을 많이 쓰는 일부 부문에는 절반으로 줄이라고 주문했다.","2030년 초까지 1GW 규모 AI 팩토리를 짓기로 해 1단계 사업비만 약 100억달러(약 13조5,000억원)에 이르는 투자 재원을 마련하려는 조치다.","데이터센터 건설은 브룩필드가 맡지만 네이버는 GPU 사용료로 10조원 넘게 내야 하며, 이를 위해 네이버클라우드에 18조7,400억원의 지급 보증을 섰다."],"url":"https://www.hankyung.com/article/2026111083181","media":"한국경제","published_local":"2026-11-10 17:38 Seoul","published_kst":"2026-11-10 17:38 KST","tickers":["035420.KS"],"names":["NAVER"],"sectors":["internet"],"related":[],"as_of":"2026-11-10"},{"rank":8,"title":"Rivian CEO says new R2 SUV, autonomy make 2027 an ‘inflection year’ as EV maker marks five years since IPO","title_ko":"리비안 CEO \"R2와 자율주행으로 2027년이 변곡점\"…3분기 인도 1만9,248대 46%↑","summary":["리비안의 RJ 스캐린지 CEO는 CNBC 인터뷰에서 중형 SUV R2와 자율주행 투자를 근거로 2027년이 회사의 변곡점이 될 것이라고 말했다.","3분기 인도량은 1만9,248대로 46% 늘었고 R2가 판매량 1위 모델이 됐으며, R2 비중 확대로 차량당 원가는 전 분기보다 1만2,000달러 넘게 개선됐다.","노멀 공장은 R2 최대 15만5,000대를 포함해 연 21만5,000대를 생산할 수 있고, 조지아 공장은 2028년 말 1단계 완공 뒤 연 30만대 규모가 된다."],"url":"https://www.cnbc.com/2026/11/10/rivian-r2-autonomy-2027-rj-scaringe.html","media":"CNBC","published_local":"2026-11-10 10:11 New_York","published_kst":"2026-11-11 00:11 KST","tickers":["RIVN"],"names":["리비안"],"sectors":["battery_ev"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-11/doc-iniyhser2350115.shtml"}],"as_of":"2026-11-10"},{"rank":9,"title":"京东方Ａ: 京东方Ａ：股东权益变动的提示性公告","title_ko":"BOE, 베이징 국유지분 40억6,000만주 지배주주로 무상 이전…베이징전공 지분 14.43%로","summary":["베이징시 국유자산감독관리위원회 결정에 따라 베이징국관이 보유한 BOE A주 40억6,333만주(10.97%)를 지배주주 베이징전공에 무상 이전하는 협약이 11월 10일 체결됐다.","이전 뒤 베이징전공의 직접 지분은 3.46%에서 14.43%로 늘고, 베이징전공과 징궈루이 펀드의 공동행동 관계는 같은 날 해소됐다.","지배주주와 실제 지배자는 계속 베이징전공이며, 심천거래소 확인과 주식 이전 등기 절차가 남아 있다."],"url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-11/075b360e-9ce4-4d5a-afdd-87948057d658.PDF","media":"深圳证券交易所","published_local":"2026-11-11 00:00 Shanghai","published_kst":"2026-11-11 01:00 KST","tickers":["000725.SZ"],"names":["BOE"],"sectors":["hardware"],"related":[{"media":"深圳证券交易所","url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-11/44453034-5f0b-4ffb-b1e6-2fa085e16e32.PDF"},{"media":"深圳证券交易所","url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-11/8ee80c72-2370-43cb-8526-0b3854e2a012.PDF"}],"as_of":"2026-11-10"},{"rank":10,"title":"Z.AI: VOLUNTARY ANNOUNCEMENT - INTENTION TO REPURCHASE H SHARES UNDER GENERAL MANDATE","title_ko":"Z.AI(즈푸), 최대 40억홍콩달러 H주 자사주 매입 계획","summary":["Z.AI는 류더빙 이사회 의장의 제안을 받아 장내에서 H주를 수시로 매입하는 자사주 매입 계획을 발표했다.","매입은 6월 22일 정기 주총에서 받은 일반 위임에 따르며, 위임은 2026년 정기 주총 종료나 주총 특별결의로 철회될 때까지 유효하다.","예상 매입 총액은 최대 40억홍콩달러, 매입 주식 수는 공시일 발행주식의 1% 이내이며, 회사는 장기 사업 전망에 대한 자신감을 보여주는 조치라고 밝혔다."],"url":"https://www1.hkexnews.hk/listedco/listconews/sehk/2026/1110/2026111000851.pdf","media":"HKEXnews","published_local":"2026-11-10 19:05 Hong_Kong","published_kst":"2026-11-10 20:05 KST","tickers":["2513.HK"],"names":["즈푸(Zhipu)"],"sectors":["ai_sw"],"related":[],"as_of":"2026-11-10"},{"rank":11,"title":"Amazon's Ring unveils flying drone and robot to patrol homes and businesses","title_ko":"아마존 링, 실내 비행 드론 카메라·보안 순찰 로봇 공개","summary":["아마존의 보안기기 자회사 링이 집 안을 날아다니는 250달러짜리 'Ring Drone Cam'과 사업장 순찰용 1,000달러짜리 'Ring Rover Cam'을 공개했다.","드론은 경보나 창문·문 센서가 작동하면 미리 정한 경로로 날아가 확인하고 최대 8분 비행 뒤 스스로 충전대로 돌아가며, 로버는 아스트로 로봇을 보안용으로 바꾼 제품이다.","링은 에코·이로와 함께 아마존의 스마트홈 확장 축이지만, 경찰 협력 등으로 사생활 침해 논란을 겪어 왔다."],"url":"https://www.cnbc.com/2026/11/10/amazons-ring-unveils-flying-drone-robot-to-patrol-homes-businesses.html","media":"CNBC","published_local":"2026-11-10 14:43 New_York","published_kst":"2026-11-11 04:43 KST","tickers":["AMZN"],"names":["아마존"],"sectors":["internet"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-10/doc-iniyhmws2538793.shtml"},{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-10/doc-iniyhmws2559175.shtml"}],"as_of":"2026-11-10"},{"rank":12,"title":"LG전자 휴머노이드 … 내년 하반기 상용화","title_ko":"LG전자, 엔비디아와 개발한 이족보행 휴머노이드 내년 하반기 상용화 추진","summary":["LG전자가 엔비디아와 협력해 개발 중인 이족보행 휴머노이드를 내년 하반기에 상용화할 계획이다.","초기 공급처는 학계와 연구·교육기관이며, 연구용 휴머노이드와 소프트웨어 개발 도구를 함께 공급해 활용 사례를 쌓는다.","바퀴형 로봇 'LG 클로이드'는 실증 중이고, 휴머노이드 핵심 부품인 액추에이터 '악시움'의 외부 판매도 추진하고 있다."],"url":"https://www.mk.co.kr/news/business/12204171","media":"매일경제","published_local":"2026-11-10 17:32 Seoul","published_kst":"2026-11-10 17:32 KST","tickers":["NVDA","066570.KS"],"names":["엔비디아","LG전자"],"sectors":["hardware","semi_chip"],"related":[],"as_of":"2026-11-10"},{"rank":1,"title":"온투이노베이션(ONTO): 8-K - Current report","title_ko":"온투이노베이션, 3분기 매출 4억970만달러 88%↑ 사상 최대…4분기 4.3억~4.5억달러 전망","summary":["온투이노베이션의 3분기 매출은 4억970만달러로 전년 대비 87.8% 늘어 분기 최대를 기록했고, 매출·영업이익률·EPS 모두 회사 가이던스 상단을 넘었다.","첨단 노드는 Atlas G6 OCD 채택으로, 첨단 패키징과 특수 디바이스는 Dragonfly G5·Firefly 검사 장비로 각각 분기 최대 매출을 냈고, 수주잔고는 13억달러를 넘었다.","4분기 전망은 매출 4억3,000만~4억5,000만달러, 비GAAP EPS 2.59~2.79달러이며, 회사는 2026년 매출 증가율이 45%를 넘을 것으로 본다."],"url":"https://www.sec.gov/Archives/edgar/data/704532/000119312526453582/0001193125-26-453582-index.htm","media":"SEC EDGAR","published_local":"2026-11-09 16:08 New_York","published_kst":"2026-11-10 06:08 KST","tickers":["ONTO"],"names":["온투이노베이션"],"sectors":["semi_equip"],"related":[],"as_of":"2026-11-09"},{"rank":2,"title":"테이크투(TTWO): 8-K - Current report","title_ko":"테이크투, 2분기 순예약 16억달러 18%↓…GTA VI 앞두고 연간 80억~82억달러 전망 유지","summary":["테이크투의 회계연도 2분기 순예약(Net Bookings)은 16억달러로 전년(19억6,000만달러)보다 18% 줄었고, GAAP 순손실은 5,400만달러로 전년(1억3,390만달러)보다 축소됐다.","반복 소비 순예약은 9% 줄어 전체의 81%를 차지했으며, 블룸버그는 'GTA VI'의 영향으로 'NBA 2K' 판매가 기대에 못 미쳤다고 전했다.","회사는 2027 회계연도 순예약 전망 80억~82억달러를 유지했고, 젤닉 CEO는 'GTA VI' 출시가 열흘 남았으며 사전 주문이 전례 없는 수준이라고 밝혔다."],"url":"https://www.sec.gov/Archives/edgar/data/946581/000162828026072175/0001628280-26-072175-index.htm","media":"SEC EDGAR","published_local":"2026-11-09 16:10 New_York","published_kst":"2026-11-10 06:10 KST","tickers":["TTWO"],"names":["테이크투"],"sectors":["internet"],"related":[{"media":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-11-09/take-two-s-nba-2k-sales-miss-expectations-due-to-grand-theft-auto-vi"}],"as_of":"2026-11-09"},{"rank":3,"title":"루시드(LCID): 8-K - Current report","title_ko":"루시드, 3분기 매출 3억5,000만달러 4%↑…PIF 지원으로 유동성 17억5,000만달러 확충","summary":["루시드의 3분기 매출은 3억5,000만달러로 전년 대비 4% 늘었고, 잉여현금 소진액은 10억4,000만달러로 전 분기보다 30% 줄었다.","분기 말 유동성은 20억달러이며, PIF의 지연인출 대출(DDTL) 한도를 17억5,000만달러 늘려 프로포마 기준 37억5,000만달러가 됐다.","회사는 이 유동성으로 2027년 4분기까지 운영할 수 있다고 봤고, 중형차 생산은 2027년 하반기로 계획돼 있으며 중기 계획과 목표는 내년 초 공개한다."],"url":"https://www.sec.gov/Archives/edgar/data/1811210/000162828026072158/0001628280-26-072158-index.htm","media":"SEC EDGAR","published_local":"2026-11-09 16:08 New_York","published_kst":"2026-11-10 06:08 KST","tickers":["LCID"],"names":["루시드"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-09"},{"rank":4,"title":"원익IPS - 연결재무제표기준영업(잠정)실적(공정공시)","title_ko":"원익IPS, 3분기 영업익 667억원 142%↑…순이익은 88% 급감","summary":["원익IPS의 3분기 연결 영업이익은 667억원으로 전년 동기보다 142.0%, 전 분기(184억원)보다 262.6% 늘었다.","매출은 3,378억원으로 전년 동기 대비 25.8%, 전 분기 대비 56.0% 증가했다.","다만 당기순이익은 33억원으로 전년 동기보다 88.2% 줄었고, 1~3분기 누적 영업이익은 958억원(+69.2%)이며 수치는 감사 전 잠정치다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261109900411","media":"DART","published_local":"2026-11-09 15:36 Seoul","published_kst":"2026-11-09 15:36 KST","tickers":["240810.KQ"],"names":["원익IPS"],"sectors":["semi_equip"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261109117600527"}],"as_of":"2026-11-09"},{"rank":5,"title":"웹툰 엔터, 3분기 영업손실 131억원…매출 전년비 4% 감소","title_ko":"네이버웹툰 美 본사, 3분기 영업손실 923만달러로 축소…매출은 4% 감소","summary":["네이버웹툰의 미국 본사 웹툰 엔터테인먼트의 3분기 영업손실은 923만달러로 전년 동기(1,488만달러)보다 38.0% 줄었고, 순손실은 747만달러였다.","매출은 3억6,278만달러로 4.0% 줄었으며, 유료 콘텐츠(-3.9%)와 IP(-27.5%)가 감소한 반면 광고는 26.2% 늘었다.","환율 효과를 제거하면 매출은 0.2% 늘었고, 김준구 CEO는 4분기에 두 자릿수 매출 성장세를 회복할 것이라고 밝혔다."],"url":"https://www.yna.co.kr/view/AKR20261110012100075","media":"연합뉴스","published_local":"2026-11-10 06:56 Seoul","published_kst":"2026-11-10 06:56 KST","tickers":["035420.KS"],"names":["NAVER"],"sectors":["internet"],"related":[],"as_of":"2026-11-09"},{"rank":6,"title":"점유율 93% 배민·쿠팡 역대최대 과징금 6천319억…사실상 담합(종합2보)","title_ko":"공정위, 쿠팡에 과징금 3,008억원…배민 포함 배달앱 역대 최대 6,319억원","summary":["공정거래위원회가 입점업체에 최혜 대우를 강제했다며 쿠팡에 3,008억원(잠정), 배달의민족에 3,311억원(잠정) 등 총 6,319억원의 과징금과 시정명령을 부과했다.","공정위는 합산 점유율 92.89%인 두 회사의 동시 요구가 담합과 유사한 효과를 냈다고 판단했고, 쿠팡은 과거 법 위반 전력으로 과징금이 20% 가중됐다.","쿠팡의 끼워팔기 혐의는 재심사하기로 했으며, 두 회사는 모두 반발하며 법적 대응을 검토하고 있다."],"url":"https://www.yna.co.kr/view/AKR20261109070252002","media":"연합뉴스","published_local":"2026-11-09 17:34 Seoul","published_kst":"2026-11-09 17:34 KST","tickers":["CPNG"],"names":["쿠팡"],"sectors":["internet"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261109070251002"},{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261109079851030"},{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12202330"}],"as_of":"2026-11-09"},{"rank":7,"title":"Nvidia faces defining test as Jensen Huang probe adds to chip stock turbulence","title_ko":"엔비디아 CEO 조사 여파 확산…핵심 인물 리스크 부각, 美 하원 3개 위원회 출석 요구","summary":["엔비디아 이사회의 젠슨 황 CEO 조사로 회사가 드문 핵심 인물 리스크에 노출되며 밸류에이션 시험대에 올랐다고 SCMP가 보도했다.","FT는 스파이 의혹을 받는 앨리스 황이 엔비디아 GPU 접근권과 알리바바와의 연결을 내세워 투자자들에게 AI 칩 거래를 제안했다고 전했다.","황 CEO는 미 하원 3개 위원회의 출석 요구를 받았고 상원 조사도 예고됐으며, 국내 반도체 업계는 현재 의혹만으로 HBM 주문이 바뀔 이유는 없다는 입장이다."],"url":"https://www.scmp.com/tech/big-tech/article/3373825/nvidia-faces-defining-test-jensen-huang-probe-adds-chip-stock-turbulence","media":"SCMP","published_local":"2026-11-09 22:30 Hong_Kong","published_kst":"2026-11-09 23:30 KST","tickers":["NVDA"],"names":["엔비디아"],"sectors":["semi_chip"],"related":[{"media":"Financial Times","url":"https://www.ft.com/content/5d8c1e1d-6ce0-4eb4-9f5c-722fa5c4841d"},{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261109120300003"},{"media":"Financial Times","url":"https://www.ft.com/content/fa3b0a35-1aa9-4f31-97b4-e4c599e3e654"},{"media":"CNBC","url":"https://www.cnbc.com/2026/11/09/nasdaq-defies-nvidia-impact-huang-faces-espionage-affair-probe.html"},{"media":"WSJ","url":"https://www.wsj.com/tech/the-chinese-woman-at-the-center-of-a-spy-probe-after-an-affair-with-jensen-huang-7bb406d2"},{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-09/doc-iniyehxu9772034.shtml"}],"as_of":"2026-11-09"},{"rank":8,"title":"字母表旗下Wing将在得州新建配送无人机工厂","title_ko":"알파벳 윙, 텍사스에 드론 공장 건설…2년간 최대 1억2,500만달러 투자","summary":["알파벳의 드론 사업부 윙이 향후 2년간 최대 1억2,500만달러를 들여 텍사스주 포트워스에 새 공장을 짓는다.","1만5,000제곱피트 규모의 공장은 연간 드론 수만 대를 생산할 수 있고, 제조 일자리를 최대 100개 만든다.","윙은 현재 5개 대도시권에 진출해 있으며, 월마트와의 협력을 바탕으로 2027년까지 약 20개 미국 시장으로 넓힐 계획이다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-09/doc-iniyearu3201297.shtml","media":"新浪财经","published_local":"2026-11-09 22:05 Shanghai","published_kst":"2026-11-09 23:05 KST","tickers":["GOOGL"],"names":["알파벳"],"sectors":["internet"],"related":[],"as_of":"2026-11-09"},{"rank":9,"title":"马斯克称特斯拉将退还部分赛博皮卡订金，并为停产决定辩护","title_ko":"머스크 \"약 8개월 뒤 사이버트럭 단종…다수 고객에 계약금 환불\"","summary":["일론 머스크 테슬라 CEO는 약 8개월 뒤 사이버트럭 생산을 끝내며, 그 전까지 최대한 만들되 다수 고객에게 계약금을 돌려줘야 한다고 밝혔다.","그는 사이버트럭이 적자 차종은 아니라고 반박했고, 복잡한 공정의 기회비용을 단종 이유로 들며 공장 공간과 자원을 사이버캡 생산에 돌리겠다는 입장이다.","테슬라는 차종별 판매량을 공개하지 않으며, 업계 추정 누적 판매량은 2023년 11월 첫 인도 이후 약 7만1,000대다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-10/doc-iniyehxs3121608.shtml","media":"新浪财经","published_local":"2026-11-10 00:14 Shanghai","published_kst":"2026-11-10 01:14 KST","tickers":["TSLA"],"names":["테슬라"],"sectors":["battery_ev"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-09/doc-iniyears6413371.shtml"}],"as_of":"2026-11-09"},{"rank":10,"title":"沪电股份: 沪电股份：关于以集中竞价交易方式回购公司股份方案暨回购报告书的公告","title_ko":"후뎬구펀, 5억~10억위안 자사주 매입 방안 공시…실제 지배자 측도 2천만~3천만위안 지분 확대","summary":["후뎬구펀이 주당 156.70위안 이하에서 5억~10억위안 규모의 자사주를 집중경쟁매매로 매입하는 방안을 공시했다.","매입 물량의 절반은 직원 지주·주식 인센티브에, 절반은 회사 가치와 주주 권익 유지에 쓰며, 상한 기준 물량은 총발행주식의 약 0.33%다.","실제 지배자 우리간 가족이 지배하는 합파이유롄(合拍友联)은 앞으로 6개월 안에 2,000만~3,000만위안어치 지분을 늘릴 계획이다."],"url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-10/56d2a170-e046-4a00-9439-99b835cf8fc0.PDF","media":"深圳证券交易所","published_local":"2026-11-10 00:00 Shanghai","published_kst":"2026-11-10 01:00 KST","tickers":["002463.SZ"],"names":["후뎬구펀(WUS)"],"sectors":["hardware"],"related":[{"media":"深圳证券交易所","url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-10/ecc49f13-eb97-4b1c-a13d-22c6fb8a0aa4.PDF"}],"as_of":"2026-11-09"},{"rank":11,"title":"华虹宏力半导体有限公司关于控股子公司转让所持华宏置业（无锡）有限公司全部股权及相关债权的公告","title_ko":"화훙반도체, 우시 부동산 자회사 지분 매각 추진…올해 순이익 약 4억1,641만위안 감소 예상","summary":["화훙반도체의 자회사 화훙반도체(우시)가 부동산 자회사 화훙즈예(우시)의 지분 100%와 관련 채권을 상하이연합재산권거래소 공개 매각으로 넘기기로 했다.","화훙즈예는 우시 공장 배후 주거·인재 아파트를 짓기 위해 세운 회사로 주택이 팔리지 않고 상업용 오피스 임대율도 낮았으며, 평가가치는 1억7,688만위안으로 장부상 순자산(약 5억9,329만위안)을 크게 밑돈다.","회사는 평가액 기준 처분 손실로 2026년 순이익이 약 4억1,641만위안, 지배주주 순이익이 약 2억1,237만위안 줄 것으로 추정했고, 매각이 끝나면 연결 대상에서 빠진다."],"url":"https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688347&id=12698411","media":"新浪财经","published_local":"2026-11-10 00:00 Shanghai","published_kst":"2026-11-10 01:00 KST","tickers":["688347.SS"],"names":["화훙반도체"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-09"},{"rank":12,"title":"삼성, 영남 60조 투자 첫발 뗐다","title_ko":"삼성SDS, 4,273억원 들여 구미 AI 데이터센터 착공…2028년 말 준공","summary":["삼성SDS가 경북 구미시 공단동에서 AI 데이터센터 착공식을 열었으며, 4,273억원을 들여 2028년 말까지 준공할 계획이다.","초기 전력 용량은 60MW로 AI 수요에 따라 늘릴 수 있게 설계됐고, 삼성 관계사의 제조 현장 로봇 전환 사업과 연계하면서 외부 고객 대상 코로케이션 사업도 함께 한다.","일반 서버에는 공냉식, 고밀도 GPU 서버에는 수냉식을 적용하며, 삼성은 이를 영남권 60조원 투자의 첫발로 삼아 울산 전고체 배터리·부산 AI 서버용 패키지 기판에도 투자할 계획이다."],"url":"https://www.hankyung.com/article/2026110941671","media":"한국경제","published_local":"2026-11-09 15:42 Seoul","published_kst":"2026-11-09 15:42 KST","tickers":["018260.KS"],"names":["삼성에스디에스"],"sectors":["ai_sw"],"related":[],"as_of":"2026-11-09"},{"rank":13,"title":"삼성·구글 AI 안경, 12일 예약판매…메타 독주에 도전","title_ko":"삼성전자, 구글 제미나이 탑재 AI 스마트 안경 12일 사전 예약…12월 출시","summary":["삼성전자가 구글 제미나이를 탑재하고 젠틀몬스터·워비파커와 협업한 스마트 안경 '인텔리전트 아이웨어'의 사전 예약을 12일 시작한다.","디스플레이 대신 카메라·마이크·스피커로 음성 명령과 시각 인식을 처리해 실시간 번역·길 안내·정보 검색을 지원하며, 촬영 중에는 LED 표시등이 켜진다.","12월 정식 출시 예정으로 한국과 미국이 초기 시장으로 거론되며, 옴디아에 따르면 메타의 AI 스마트 안경 출하 점유율은 지난해 85.2%, 올해 상반기 81.3%다."],"url":"https://www.yna.co.kr/view/AKR20261109072000017","media":"연합뉴스","published_local":"2026-11-09 11:35 Seoul","published_kst":"2026-11-09 11:35 KST","tickers":["005930.KS"],"names":["삼성전자"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-09"},{"rank":14,"title":"深圳中科飞测科技股份有限公司关于以集中竞价交易方式回购公司股份方案的公告","title_ko":"중커페이처, 1억~1억5,000만위안 자사주 매입 방안 이사회 통과","summary":["중커페이처 이사회가 11월 9일 1억~1억5,000만위안 규모의 자사주를 주당 440위안 이하에서 집중경쟁매매로 매입하는 방안을 통과시켰다.","재원은 자체·조달 자금이며, 자사주 매입 전용 대출은 중신은행 선전지점에서 최대 1억3,500만위안의 대출 확약을 받았다.","매입 주식은 향후 주식 인센티브나 직원 지주에 쓰며, 실제 지배자인 천루 회장이 11월 3일 매입을 제안했다."],"url":"https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688361&id=12697992","media":"新浪财经","published_local":"2026-11-10 00:00 Shanghai","published_kst":"2026-11-10 01:00 KST","tickers":["688361.SS"],"names":["중커페이처"],"sectors":["semi_equip"],"related":[],"as_of":"2026-11-09"},{"rank":15,"title":"中微半导体设备（上海）股份有限公司关于以集中竞价交易方式首次回购公司股份的公告","title_ko":"중미반도체, 4억~5억위안 자사주 매입 첫 집행…약 1,999만위안어치","summary":["중미반도체(AMEC)가 11월 9일 집중경쟁매매로 자사주 7만9,600주(총발행주식의 0.008%)를 처음 매입했다.","매입 가격은 주당 247.51~257.00위안이며 지급 총액은 1,998만5,626위안이다.","11월 5일 이사회가 통과시킨 4억~5억위안(주당 433.04위안 이하) 매입 방안의 첫 집행으로, 매입 주식은 주식 인센티브나 직원 지주에 쓴다."],"url":"https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688012&id=12697988","media":"新浪财经","published_local":"2026-11-10 00:00 Shanghai","published_kst":"2026-11-10 01:00 KST","tickers":["688012.SS"],"names":["중미반도체(AMEC)"],"sectors":["semi_equip"],"related":[],"as_of":"2026-11-09"},{"rank":16,"title":"구글, 보안 강화한 새 AI칩 공개…TPU 8tx·TPU 8i MAX 발표","title_ko":"구글, 보안 강화 TPU 8tx·메모리 늘린 TPU 8i Max 공개…7개월 만에 신제품","summary":["구글이 기업 기밀 정보를 하드웨어 차원에서 보호하는 TPU 8tx와 연산 성능을 높인 TPU 8i Max를 9일 공개해 TPU 제품군을 네 종류로 늘렸다.","8tx는 학습용 8t에 데이터 처리 공간 격리 등 보안 기능을 더했고, 8i Max는 추론용 8i 두 개를 한 패키지로 묶어 연산 능력을 두 배로, HBM 용량을 33% 늘린 384GB로 키웠다.","구글은 모듈화로 개발 기간을 줄여 7개월 만에 신제품을 냈으며, 지난달에는 엔비디아 GPU 사용자의 이전을 돕는 소프트웨어 '토치TPU'를 공개했다."],"url":"https://www.hankyung.com/article/2026110957481","media":"한국경제","published_local":"2026-11-09 22:15 Seoul","published_kst":"2026-11-09 22:15 KST","tickers":["GOOGL"],"names":["알파벳"],"sectors":["internet"],"related":[{"media":"Bloomberg","url":"https://www.bloomberg.com/news/videos/2026-11-09/google-rolls-out-new-ai-chips-to-challenge-nvidia-video"},{"media":"한국경제","url":"https://www.hankyung.com/article/202611093480i"}],"as_of":"2026-11-09"},{"rank":1,"title":"Nvidia Board to Probe Spying Case After CEO Jensen Huang Admits Infidelity","title_ko":"엔비디아 이사회, CEO 겨냥 해외 정보기관 공작 의혹 독립 조사 착수…미 의회도 브리핑 요청","summary":["엔비디아 이사회가 젠슨 황 CEO가 해외 정보기관의 표적이 됐다는 보도와 관련해 독립 조사에 착수했다.","이사회는 국가안보나 회사 기밀이 침해됐다고 볼 이유는 없다면서도 모든 정보를 검토하겠다고 했고, 회사는 황 CEO가 중단 없이 경영을 이어간다고 밝혔다.","미 하원 공화당 위원장 3명이 3분기 실적 발표(11월 17일) 다음 날인 11월 18일 비공개 브리핑을 요청했으며, 민주당에서도 의회 조사 요구가 나오고 있다."],"url":"https://www.bloomberg.com/news/articles/2026-11-08/nvidia-board-to-probe-spying-case-after-ceo-jensen-huang-admits-infidelity","media":"Bloomberg","published_local":"2026-11-08 15:00 New_York","published_kst":"2026-11-09 05:00 KST","tickers":["NVDA"],"names":["엔비디아"],"sectors":["semi_chip"],"related":[{"media":"CNBC","url":"https://www.cnbc.com/2026/11/08/nvidia-jensen-huang-investigation-china-spy.html"},{"media":"CNBC","url":"https://www.cnbc.com/2026/11/08/jensen-huang-nvidia-china-spy-congress.html"},{"media":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-11-08/read-the-memos-from-nvidia-s-board-and-ceo-jensen-huang"},{"media":"Financial Times","url":"https://www.ft.com/content/494e9731-d195-40e0-9ad4-cf7811037c05"}],"as_of":"2026-11-08"},{"rank":2,"title":"SK이노베이션 - 정정신고서제출요구 ( 2026.10.28. 제출 증권신고서(합병) )","title_ko":"SK이노베이션 합병 증권신고서에 정정 요구…신고서 효력 정지","summary":["SK이노베이션이 10월 28일 제출한 합병 증권신고서에 대해 11월 6일 정정신고서 제출 요구를 받았다.","공시는 형식 미비나 중요사항 기재 누락·불분명 등을 사유로 들었고, 해당 신고서는 요구일부터 수리되지 않은 것으로 보며 효력이 정지된다.","청약일 등 발행 일정이 바뀔 수 있으며, 3개월 안에 정정신고서를 내지 않으면 신고서는 철회된 것으로 간주된다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261106100004","media":"DART","published_local":"2026-11-06 20:00 Seoul","published_kst":"2026-11-06 20:00 KST","tickers":["096770.KS"],"names":["SK이노베이션"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-08"},{"rank":3,"title":"Microsoft plans to use fewer neoclouds as AI buildout shows signs of strain","title_ko":"MS, 네오클라우드 협력사 축소 추진…자체 데이터센터 우선, 오라클 계약도 미갱신","summary":["마이크로소프트가 소수 핵심 공급사 중심으로 네오클라우드 협력사를 줄이고 자체 데이터센터 확충을 우선하고 있다고 CNBC가 소식통을 인용해 보도했다.","어느 업체와의 거래를 끊을지는 아직 평가 단계이며, 소식통 2명은 MS가 오라클과의 계약도 갱신하지 않기로 했다고 전했다.","MS의 직전 분기 설비투자·금융리스는 452억달러이고 회계연도 하반기 지출은 더 늘어날 예정이며, 코어위브와 네비우스는 다음 주 실적을 발표한다."],"url":"https://www.cnbc.com/2026/11/06/microsoft-moves-to-consolidate-its-relationships-with-neoclouds-in-ai.html","media":"CNBC","published_local":"2026-11-06 13:40 New_York","published_kst":"2026-11-07 03:40 KST","tickers":["MSFT"],"names":["마이크로소프트"],"sectors":["ai_sw"],"related":[],"as_of":"2026-11-08"},{"rank":4,"title":"Tesla to wind down Cybertruck production in Texas next year to ramp Cybercab, Musk says","title_ko":"테슬라, 내년 중반 텍사스 사이버트럭 생산 종료…사이버캡 증산에 공간 활용","summary":["일론 머스크 CEO가 텍사스 기가팩토리의 사이버트럭 생산을 내년 중반께 종료하겠다고 X에 밝혔다.","확보한 공간은 사이버캡 로보택시 생산에 쓰이며, 사이버트럭은 텍사스 공장에서만 만들어 왔으나 다른 공장으로 옮길지는 밝히지 않았다.","콕스오토모티브는 지난해 미국 내 사이버트럭 판매를 20,237대로 추정했고, 이는 전년 38,965대보다 48% 줄어든 수치다."],"url":"https://www.cnbc.com/2026/11/06/tesla-cybertruck-texas-musk.html","media":"CNBC","published_local":"2026-11-06 08:12 New_York","published_kst":"2026-11-06 22:12 KST","tickers":["TSLA"],"names":["테슬라"],"sectors":["battery_ev"],"related":[{"media":"SCMP","url":"https://www.scmp.com/news/world/united-states-canada/article/3373598/teslas-musk-pulls-plug-cybertruck-robotaxi-push-after-years-poor-sales"}],"as_of":"2026-11-08"},{"rank":5,"title":"맞춤형 HBM이 바꾼 SK·삼성 인사…기술통이 미주사업 이끈다","title_ko":"SK하이닉스, 사장급 미주총괄 신설…HBM 개발 수장 안현 사장 선임","summary":["SK하이닉스가 사장급 미주총괄을 신설하고 HBM·소캠 등 AI 메모리 개발을 이끌어 온 안현 개발총괄 사장을 선임했다.","미국 빅테크 고객과 AI 가속기 설계 단계부터 협업해야 물량을 따낼 수 있고, 내년부터 맞춤형 HBM 시대가 본격화하는 데 대비한 인사다.","내달 3일께 후속 인사와 조직 개편으로 미주사업 인력을 보강하며, 삼성전자도 2024년 12월 메모리 솔루션 개발 출신을 반도체 미주총괄에 선임했다."],"url":"https://www.yna.co.kr/view/AKR20261108042900003","media":"연합뉴스","published_local":"2026-11-09 06:09 Seoul","published_kst":"2026-11-09 06:09 KST","tickers":["000660.KS"],"names":["SK하이닉스"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-08"},{"rank":6,"title":"沪电股份: 沪电股份：关于董事长提议回购公司股份的提示性公告","title_ko":"후뎬구펀 회장, 5억~10억위안 자사주 매입 제안","summary":["후뎬구펀(WUS) 천메이팡 회장이 5억~10억위안 규모의 A주 자사주 매입을 이사회에 제안했다고 공시했다.","매입 주식은 직원지주·주식보상, 자본금 감소 또는 회사 가치·주주 권익 유지에 쓰이며, 구체적 용도는 승인된 방안에 따른다.","매입가 상한은 결의 전 30거래일 평균가의 150%이고, 이사회 또는 주주총회 승인을 거쳐야 실행된다."],"url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-07/6d9ae8dc-4ab5-4ac1-b11d-5225e70f06cf.PDF","media":"深圳证券交易所","published_local":"2026-11-07 00:00 Shanghai","published_kst":"2026-11-07 01:00 KST","tickers":["002463.SZ"],"names":["후뎬구펀(WUS)"],"sectors":["hardware"],"related":[],"as_of":"2026-11-08"},{"rank":7,"title":"赣锋锂业: 赣锋锂业：关于公司实际控制人、董事长提议回购公司股份的公告","title_ko":"간펑리튬 회장, 2억~4억위안 자사주 매입 제안","summary":["간펑리튬의 실제 지배자인 리량빈 회장이 2억~4억위안 규모의 A주 자사주 매입을 이사회에 제안했다고 공시했다.","매입 주식은 회사 가치·주주 권익 유지 용도로, 결과 공시 12개월 뒤 장내 매각하며 3년 안에 다 팔지 못하면 소각한다.","매입가 상한은 결의 전 30거래일 평균가의 150%, 실행 기간은 이사회 승인 후 12개월이며 자금원에 자사주 매입 대출이 포함된다."],"url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-07/b39f77b7-fb31-4290-af04-2eb594f4fb72.PDF","media":"深圳证券交易所","published_local":"2026-11-07 00:00 Shanghai","published_kst":"2026-11-07 01:00 KST","tickers":["002460.SZ"],"names":["간펑리튬"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-08"},{"rank":8,"title":"Meta chief strategy officer Dave Wehner leaves to join AI infrastructure startup Fireworks as CFO","title_ko":"메타 최고전략책임자 데이브 웨너 퇴사…AI 스타트업 Fireworks CFO로 이동","summary":["메타의 데이브 웨너 최고전략책임자가 회사를 떠나 AI 스타트업 Fireworks의 CFO를 맡는다.","웨너는 2012년 당시 페이스북에 합류해 2014~2022년 CFO를 지냈다.","Fireworks는 오픈 모델 추론·학습 플랫폼으로 7월 시리즈D에서 175억달러 가치를 인정받았고, 엔비디아와 세쿼이아 캐피털도 투자했다."],"url":"https://www.cnbc.com/2026/11/07/dave-wehner-meta-fireworks-cfo.html","media":"CNBC","published_local":"2026-11-07 17:01 New_York","published_kst":"2026-11-08 07:01 KST","tickers":["META"],"names":["메타"],"sectors":["internet"],"related":[],"as_of":"2026-11-08"},{"rank":9,"title":"李柯回应收购玛莎拉蒂传闻","title_ko":"BYD 부회장 \"마세라티 관심은 몇 년 전 얘기\"…자체 브랜드 집중","summary":["BYD의 리커 부회장이 마세라티 인수설에 대해 몇 년 전에는 관심이 더 컸지만 지금은 자체 브랜드를 키우는 쪽이 맞다고 밝혔다.","양왕 U9 Xtreme이 503.17km/h로 양산차 최고속도 기록을 세운 아부다비 행사에서 나온 인터뷰다.","리커 부회장은 매년 핵심 기술을 내놓겠다며, 이번 차량에 쓴 고전압 구조 등을 다른 BYD 차종에도 적용할 수 있다고 말했다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-08/doc-inixyrxe4008934.shtml","media":"新浪财经","published_local":"2026-11-08 09:58 Shanghai","published_kst":"2026-11-08 10:58 KST","tickers":["002594.SZ"],"names":["BYD"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-08"},{"rank":1,"title":"华虹宏力: 2026年第三季度报告","title_ko":"화훙반도체, 3분기 순이익 136%↑…화리웨이 인수 반영, 4분기 매출 10.8억~10.9억달러 전망","summary":["화훙반도체의 3분기 매출은 67.06억위안(+13.95%), 지배주주 순이익은 8.35억위안(+136.14%)이었다.","3분기에 화리웨이(华力微) 지분 97.5% 인수를 마쳐 이후 실적에 포함되며, 높은 가동률 속에 출하량과 평균판매가격이 함께 올랐고 12인치 매출 비중은 70.7%였다.","4분기 매출 가이던스는 10.8억~10.9억달러, 매출총이익률은 25~26%이며, 증설 프로젝트는 계획대로 진행 중이다."],"url":"https://static.sse.com.cn/disclosure/listedinfo/announcement/c/new/2026-11-06/688347_20261106_0ZES.pdf","media":"上海证券交易所","published_local":"2026-11-06 16:00 Shanghai","published_kst":"2026-11-06 17:00 KST","tickers":["688347.SS"],"names":["화훙반도체"],"sectors":["semi_chip"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/hkstock/marketalerts/2026-11-06/doc-inixuiza8886134.shtml"},{"media":"上海证券交易所","url":"https://static.sse.com.cn/disclosure/listedinfo/announcement/c/new/2026-11-06/688347_20261106_F44G.pdf"}],"as_of":"2026-11-06"},{"rank":2,"title":"中际旭创: 中际旭创：关于股份回购事项的公告","title_ko":"중지쉬촹, 주요 고객 주문 2027년 전체 거의 확보…1~3분기 순이익 212%↑","summary":["중지쉬촹(이노라이트)은 주요 고객 주문이 2027년 전체를 거의 커버하고, 일부 핵심 고객은 2028년 수요 가이던스까지 제시했다고 공시했다.","1~3분기 매출은 695.47억위안(+178.13%), 지배주주 순이익은 222.38억위안(+211.81%)이며, 3분기 성장은 800G·1.6T 출하 확대, 특히 1.6T 매출 가속이 이끌었다.","9월 매입한 자사주 565만주(약 49.97억위안)는 소각 용도로 바꿨고, NPO·XPO 등 차세대 광연결 제품 수요는 내년 하반기부터 본격화할 것으로 내다봤다."],"url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-06/2f157d83-5aaf-486b-be0b-b9c0f01bf8e6.PDF","media":"深圳证券交易所","published_local":"2026-11-06 11:39 Shanghai","published_kst":"2026-11-06 12:39 KST","tickers":["300308.SZ"],"names":["중지쉬촹(이노라이트)"],"sectors":["hardware"],"related":[],"as_of":"2026-11-06"},{"rank":3,"title":"쿠팡 6천억대 '개인정보 과징금' 중 2천억원 효력 정지(종합)","title_ko":"법원, 쿠팡 개인정보 과징금 6천억원대 중 2,011억원 효력 정지","summary":["서울행정법원이 개인정보위가 쿠팡에 부과한 과징금 2,011억원과 시정·공표명령의 효력을 본안 1심 선고 후 30일까지 정지했다.","해당 처분은 회원 약 1,117만명의 타사 웹·앱 활동기록을 무단 수집해 식별 가능한 상태로 저장한 데 대해 올해 6월 의결된 것이다.","3,750만여명 개인정보 유출 관련 4,236억원 과징금은 전날 다른 재판부가 집행정지를 받아들이지 않아, 시정·공표명령만 정지된 상태다."],"url":"https://www.yna.co.kr/view/AKR20261106100951004","media":"연합뉴스","published_local":"2026-11-06 14:01 Seoul","published_kst":"2026-11-06 14:01 KST","tickers":["CPNG"],"names":["쿠팡"],"sectors":["internet"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261106100900004"},{"media":"연합인포맥스","url":"https://news.einfomax.co.kr/news/articleView.html?idxno=4443510"}],"as_of":"2026-11-06"},{"rank":4,"title":"\"마이크론, 대만 신공장 건설 중단…노사간 보상갈등\"","title_ko":"마이크론, 대만 노사 갈등에 타오위안 신공장 건설 사실상 중단","summary":["마이크론이 대만 노사 임금 갈등으로 7월 착공한 타오위안 신공장(Fab 11E) 건설을 사실상 중단했다고 블룸버그가 소식통을 인용해 보도했다.","이 공장은 30억~45억달러를 들여 HBM과 첨단 D램을 생산해 2028년부터 공급할 계획이었으며, 대만은 마이크론 전 세계 D램 생산의 60%를 맡고 있다.","마이크론은 가동 중인 대만 라인은 정상 운영 중이라고만 밝혔고, 노조는 영업이익의 15%를 직원에게 분배하라며 전면 재협상을 요구하고 있다."],"url":"https://www.yna.co.kr/view/AKR20261106064700009","media":"연합뉴스","published_local":"2026-11-06 10:29 Seoul","published_kst":"2026-11-06 10:29 KST","tickers":["MU"],"names":["마이크론"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-06"},{"rank":5,"title":"오라클, 초대형 데이터센터 지연…\"전력인프라 허가 차질\"","title_ko":"오라클 1,650억달러 '프로젝트 주피터' 데이터센터, 전력 인허가 차질로 최종 승인 내년으로","summary":["오라클이 오픈AI용으로 뉴멕시코주에서 추진하는 1,650억달러 규모 '프로젝트 주피터' 데이터센터가 전력 인프라 인허가 문제로 차질을 빚고 있다고 블룸버그가 보도했다.","전력 인프라 개발사가 신청서를 대폭 수정하면서 대기오염 심사 기한(11월 23일)이 연장되고 12월 7일 공청회가 취소돼, 연료전지 발전설비 최종 승인은 내년으로 넘어갔다.","이날 오라클 주가는 6.96%, 연료전지를 공급하는 블룸에너지는 16.4% 하락했다."],"url":"https://www.yna.co.kr/view/AKR20261106035100009","media":"연합뉴스","published_local":"2026-11-06 09:13 Seoul","published_kst":"2026-11-06 09:13 KST","tickers":["ORCL"],"names":["오라클"],"sectors":["ai_sw"],"related":[{"media":"한국경제","url":"https://www.hankyung.com/article/202611060696i"}],"as_of":"2026-11-06"},{"rank":6,"title":"英伟达应对数据中心监管阻力：改造阿波罗旗下旧电信楼宇","title_ko":"엔비디아, 아폴로 산하 통신사 전화국 건물 개조해 美 20개 주 AI 추론 데이터센터망 추진","summary":["엔비디아가 아폴로 산하 통신사 Brightspeed의 기존 전화국 건물을 개조해 미국 20개 주에 소형 AI 데이터센터망을 구축하는 방안을 추진 중이라고 신랑재경이 소식통을 인용해 보도했다.","신규 데이터센터 규제 강화 움직임을 피하려는 대안으로, Brightspeed의 130여 개 건물은 합계 약 1GW의 전력을 쓸 수 있는 것으로 평가됐다.","이르면 2027년 1분기 일부 건물에 베라 루빈 서버 랙을 설치할 계획이며, 이 칩을 누가 구매할지는 아직 정해지지 않았다."],"url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-06/doc-inixuqhu5023747.shtml","media":"新浪财经","published_local":"2026-11-06 14:43 Shanghai","published_kst":"2026-11-06 15:43 KST","tickers":["NVDA"],"names":["엔비디아"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-06"},{"rank":7,"title":"구글, 와이오밍주 데이터센터 건설 발표…연료전지 사용","title_ko":"구글, 와이오밍에 170억달러 데이터센터 건설…연료전지 702MW로 전력 일부 조달","summary":["구글이 와이오밍주 래러미 카운티에 170억달러를 투입해 주내 첫 데이터센터를 짓겠다고 발표했다.","전력 일부는 블룸에너지 연료전지 기반 702MW 천연가스 설비에서 공급받고, 냉각용수를 줄이기 위해 공랭식을 채택한다.","구글은 데이터센터 전력 비용을 전액 부담할 계획이며, AEP는 지난달 이 프로젝트에 40억달러를 투자하겠다고 밝혔다."],"url":"https://www.yna.co.kr/view/AKR20261106025000009","media":"연합뉴스","published_local":"2026-11-06 08:40 Seoul","published_kst":"2026-11-06 08:40 KST","tickers":["GOOGL"],"names":["알파벳"],"sectors":["internet"],"related":[],"as_of":"2026-11-06"},{"rank":8,"title":"엔비디아, 네이버에 1조3천412억원 납입 완료…지분 4.13% 확보","title_ko":"엔비디아, 네이버에 1조3,412억원 납입 완료…지분 4.13% 확보","summary":["엔비디아가 네이버 제3자 배정 유상증자에 10억달러(1조3,412억원)를 납입해 지분 약 4.13%를 확보했다.","네이버는 보통주 655만8,435주를 발행했으며, 실제 발행 규모는 11월 3일 확정한 규모와 같다.","네이버는 자금을 AI 팩토리 신사업에 투입해 데이터센터 '각 세종'을 거점으로 엔비디아 GPU 기반 AI 인프라와 GPUaaS 사업을 확대할 계획이다."],"url":"https://www.yna.co.kr/view/AKR20261106136800017","media":"연합뉴스","published_local":"2026-11-06 15:57 Seoul","published_kst":"2026-11-06 15:57 KST","tickers":["NVDA","035420.KS"],"names":["엔비디아","NAVER"],"sectors":["internet","semi_chip"],"related":[{"media":"DART","url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261106800553"}],"as_of":"2026-11-06"},{"rank":9,"title":"애플, 10조원 회사채 발행…주문 4배 몰려","title_ko":"애플, 회사채로 75억달러 조달…주문 4배 이상 몰려","summary":["애플이 7개 만기 투자등급 회사채로 75억달러를 조달했으며, 주문은 최대 310억달러로 발행액의 4배를 넘었다고 블룸버그가 보도했다.","10년물 스프레드는 국채 대비 0.55%p로 예상보다 0.25%p 낮았고, MS(0.65%p)·메타(1.6%p)·오라클(3.1%p)보다 낮았다.","자금은 자사주 매입을 포함한 일반 운영 목적에 쓰이며, 애플의 직전 회사채 발행은 2025년 5월 45억달러였다."],"url":"https://www.yna.co.kr/view/AKR20261106019500009","media":"연합뉴스","published_local":"2026-11-06 07:54 Seoul","published_kst":"2026-11-06 07:54 KST","tickers":["AAPL"],"names":["애플"],"sectors":["hardware"],"related":[],"as_of":"2026-11-06"},{"rank":10,"title":"江波龙: 江波龙：关于公司近期生产经营情况及加强回购与分红等措施的公告","title_ko":"장보룽, 자사주 8억위안 매입·올해 배당 12.69억위안…기업용 매출 40억위안 돌파","summary":["장보룽(롱시스)은 9월 8~18일 자사주 229만주(A주 0.53%)를 약 8억위안에 매입했고, 2차 중간배당까지 마치면 올해 누적 배당이 12.69억위안이 된다고 공시했다.","1~9월 기업용 사업 매출은 40억위안을 넘었으며, 자체 SSD·UFS 컨트롤러로 AMD·퀄컴 등과 온디바이스 AI 협력을 진행하고 있다.","렉사(Lexar) 브랜드 매출은 2026년 연간 10억달러 돌파가 예상되며, 앞으로 자사주 매입과 배당으로 주주환원을 강화하겠다고 밝혔다."],"url":"https://disc.static.szse.cn/download/disc/disk03/finalpage/2026-11-06/757b7ad8-7e8a-44cd-8fba-02118085ef79.pdf","media":"深圳证券交易所","published_local":"2026-11-06 12:23 Shanghai","published_kst":"2026-11-06 13:23 KST","tickers":["301308.SZ"],"names":["장보룽"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-06"},{"rank":1,"title":"Qualcomm stock drops 7% on weak earnings forecast as memory shortage weighs on smartphone sales","title_ko":"퀄컴, 분기 실적은 예상 상회했지만 가이던스 하회…메모리 가격 상승에 스마트폰 칩 부진","summary":["퀄컴은 분기 실적이 시장 예상을 웃돌았지만 다음 분기 EPS 가이던스(2.15~2.35달러)가 기대치(2.27달러)에 못 미치며 시간외 주가가 7% 하락했다.","메모리 가격 상승으로 스마트폰 제조사들이 가격을 올리면서 수요가 위축돼 핸드셋 칩 매출이 26% 줄어든 51.4억달러에 그쳤다.","다음 분기 매출 가이던스는 104억~112억달러이며, 아몬 CEO는 데이터센터 매출을 이번 분기 6.5억달러에서 2027회계연도 50억달러로 키우겠다고 제시했다."],"url":"https://www.cnbc.com/2026/11/04/qualcomm-qcom-earnings-report-q4-2026.html","media":"CNBC","published_local":"2026-11-04 18:38 New_York","published_kst":"2026-11-05 08:38 KST","tickers":["QCOM"],"names":["퀄컴"],"sectors":["semi_chip"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-06/doc-inixthph8599658.shtml"}],"as_of":"2026-11-05"},{"rank":2,"title":"카카오 IR - 연결재무제표기준영업(잠정)실적(공정공시)","title_ko":"카카오, 3분기 영업익 2,403억원…1,500억원 자사주 매입 후 전량 소각","summary":["카카오의 3분기 연결 영업이익은 2,403억원으로, 중단영업을 반영해 재작성한 전년 동기(2,238억원)보다 7.4% 늘었다.","매출은 2조867억원으로 재작성 기준 6.3% 증가했으며, 카카오게임즈·카카오헬스케어는 매각에 따라 중단영업으로 분류됐다.","1,500억원(약 515만주) 규모 자사주를 2026-11-06~2027-02-05 장내 매수해 전량 소각할 예정이며, AI 에이전트 '카나나 스페이스'는 다음 달 시범 서비스에 들어간다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261105800007","media":"DART","published_local":"2026-11-05 08:02 Seoul","published_kst":"2026-11-05 08:02 KST","tickers":["035720.KS"],"names":["카카오"],"sectors":["internet"],"related":[{"media":"DART","url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261105000008"},{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12198690"},{"media":"DART","url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261105800008"}],"as_of":"2026-11-05"},{"rank":3,"title":"LG화학 - 연결재무제표기준영업(잠정)실적(공정공시)","title_ko":"LG화학, 3분기 영업익 5,612억원 17.4%↓…석유화학 적자 전환","summary":["LG화학의 3분기 연결 영업이익은 5,612억원으로 전년 동기 대비 17.4% 줄었고, 당기순손익은 6,000억원 손실로 적자 전환했다.","매출은 15조4,960억원(+34.0%)이었으나 석유화학 부문이 원료가 역래깅에 따른 스프레드 축소 등으로 영업손실 1,756억원을 냈다.","자회사 LG에너지솔루션은 영업이익 7,560억원으로 수익성이 개선됐고, 회사는 LGES 지분 매각 세후 현금 유입액의 약 20%를 주주환원에 쓰기로 했다."],"url":"https://dart.fss.or.kr/dsaf001/main.do?rcpNo=20261105800303","media":"DART","published_local":"2026-11-05 13:35 Seoul","published_kst":"2026-11-05 13:35 KST","tickers":["051910.KS"],"names":["LG화학"],"sectors":["battery_ev"],"related":[{"media":"연합뉴스","url":"https://www.yna.co.kr/view/AKR20261105101952527"},{"media":"매일경제","url":"https://www.mk.co.kr/news/business/12198641"}],"as_of":"2026-11-05"},{"rank":4,"title":"에어비앤비(ABNB): 8-K - Current report","title_ko":"에어비앤비, 3분기 매출 49억달러 19%↑…4분기 매출 16~18% 성장 전망","summary":["에어비앤비의 3분기 매출은 49억달러로 전년 대비 19% 늘었고, 순이익은 19억달러를 기록했다.","숙박일수의 두 자릿수 성장과 평균 객실요금(ADR) 상승이 매출을 이끌었으며, 조정 EBITDA는 25억달러(마진 52%), 잉여현금흐름은 14억달러였다.","4분기 매출 가이던스는 32.2억~32.8억달러로 전년 대비 16~18% 성장(환율 효과 약 2%p 포함)을 제시했다."],"url":"https://www.sec.gov/Archives/edgar/data/1559720/000119312526449727/0001193125-26-449727-index.htm","media":"SEC EDGAR","published_local":"2026-11-05 16:02 New_York","published_kst":"2026-11-06 06:02 KST","tickers":["ABNB"],"names":["에어비앤비"],"sectors":["internet"],"related":[{"media":"Bloomberg","url":"https://www.bloomberg.com/news/articles/2026-11-05/airbnb-posts-19-revenue-jump-as-chesky-hails-growth-mode"},{"media":"SEC EDGAR","url":"https://www.sec.gov/Archives/edgar/data/1559720/000155972026000032/0001559720-26-000032-index.htm"}],"as_of":"2026-11-05"},{"rank":5,"title":"MP머티리얼즈(MP): 8-K - Current report","title_ko":"MP머티리얼즈, 3분기 NdPr 판매 94%↑…GM향 자석 매출 4분기부터 인식","summary":["MP머티리얼즈의 3분기 매출과 PPA 수익 합계는 1억5,580만달러였고, 순손실은 2,070만달러로 전년보다 2,110만달러 줄었다.","NdPr 생산량은 1,018톤(+41%), 판매량은 1,020톤(+94%)이었으며 소재 부문 조정 EBITDA는 4,780만달러였다.","GM향 자석 품질 인증을 마쳐 4분기부터 판매용 납품과 매출이 시작되며, 자석 부문은 3분기 매출 1,860만달러를 기록했다."],"url":"https://www.sec.gov/Archives/edgar/data/1801368/000180136826000056/0001801368-26-000056-index.htm","media":"SEC EDGAR","published_local":"2026-11-05 16:04 New_York","published_kst":"2026-11-06 06:04 KST","tickers":["MP"],"names":["MP머티리얼즈"],"sectors":["battery_ev"],"related":[],"as_of":"2026-11-05"},{"rank":6,"title":"이오스에너지(EOSE): 8-K - Current report","title_ko":"이오스에너지, 3분기 매출 8,270만달러 171%↑…연간 전망 범위 하단 재확인","summary":["이오스에너지의 3분기 매출은 8,270만달러로 전년 대비 171% 늘어 분기 최대를 기록했다.","매출총이익률은 전년 대비 58%p, 조정 EBITDA 마진은 96%p 개선됐고, 미 에너지부 대출 2차 트랜치의 첫 선급금 8,700만달러를 받았다.","수주잔고는 7억6,500만달러(3.2GWh)로 전 분기보다 5% 줄었으며, 연간 매출 전망은 3억~3억5,000만달러 범위의 하단으로 유지했다."],"url":"https://www.sec.gov/Archives/edgar/data/1805077/000162828026070528/0001628280-26-070528-index.htm","media":"SEC EDGAR","published_local":"2026-11-05 06:47 New_York","published_kst":"2026-11-05 20:47 KST","tickers":["EOSE"],"names":["이오스에너지"],"sectors":["battery_ev"],"related":[{"media":"SEC EDGAR","url":"https://www.sec.gov/Archives/edgar/data/1805077/000162828026070529/0001628280-26-070529-index.htm"}],"as_of":"2026-11-05"},{"rank":7,"title":"Chinese AI lab Moonshot turned to Europe for Nvidia Blackwell access amid U.S. China curbs, sources tell CNBC","title_ko":"中 AI 연구소 문샷, 수출통제 피해 유럽 데이터센터서 엔비디아 블랙웰 임차 추진","summary":["중국 AI 연구소 문샷AI가 올해 유럽 네오클라우드 업체로부터 엔비디아 블랙웰 GPU 연산력을 임차하는 방안을 논의했다고 CNBC가 소식통 4명을 인용해 보도했다.","블랙웰은 대중 수출통제 대상이지만, 해외 데이터센터를 통한 원격 접근은 현행법상 규제 당국의 권한이 넓지 않은 사각지대로 남아 있다.","미 백악관은 7월 문샷이 태국 시설을 통해 블랙웰에 접근했다고 지적한 바 있으며, 엔비디아와 상무부는 논평 요청에 응하지 않았다."],"url":"https://www.cnbc.com/2026/11/05/moonshot-ai-nvidia-chips-europe-china.html","media":"CNBC","published_local":"2026-11-05 08:34 New_York","published_kst":"2026-11-05 22:34 KST","tickers":["NVDA"],"names":["엔비디아"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-05"},{"rank":8,"title":"Microsoft Sours on Neoclouds IREN, Nebius, Nscale on Delays, Costs","title_ko":"MS, IREN·Nebius·Nscale 등 네오클라우드 계약 재검토…지연·비용 부담에 자체 데이터센터 우선","summary":["마이크로소프트가 IREN·Nebius·Nscale의 일부 데이터센터 프로젝트 감독을 강화하고 위험도가 높은 프로젝트에서 철수하고 있다고 블룸버그가 소식통을 인용해 보도했다.","IREN의 텍사스 프로젝트는 배선 문제 등으로 완공이 수주~수개월 늦어질 수 있고, MS는 Nscale과의 텍사스 계약 확대를 거절하고 웨스트버지니아 1.35GW 임차 의향서에서도 빠졌다.","MS는 지난 1년간 2,000억달러 이상의 데이터센터 임대 약정을 추가했으며, 현재는 신규 네오클라우드 계약보다 자체 데이터센터 확충에 집중하고 있다."],"url":"https://www.bloomberg.com/news/articles/2026-11-05/microsoft-sours-on-neoclouds-iren-nebius-nscale-on-delays-costs","media":"Bloomberg","published_local":"2026-11-05 10:42 New_York","published_kst":"2026-11-06 00:42 KST","tickers":["MSFT"],"names":["마이크로소프트"],"sectors":["ai_sw"],"related":[{"media":"新浪财经","url":"https://finance.sina.com.cn/stock/usstock/c/2026-11-06/doc-inixtnvn9139462.shtml"},{"media":"Financial Times","url":"https://www.ft.com/content/668e6ef8-88a1-4bef-8664-8f495baf09f8"}],"as_of":"2026-11-05"},{"rank":9,"title":"Chinese chipmaker Hua Hong bets big on silicon photonics amid AI boom","title_ko":"화훙반도체, AI 수요 겨냥해 실리콘 포토닉스 생산능력 대폭 확대 추진","summary":["중국 2위 파운드리 화훙반도체가 AI 인프라 수요를 겨냥해 실리콘 포토닉스 사업을 공격적으로 확대한다.","바이펑 회장은 실적 콘퍼런스콜에서 광모듈 안의 모든 실리콘 기반 소자에 참여하겠다며, 실리콘 포토닉스와 전력관리 칩을 생산능력을 크게 늘릴 두 분야로 꼽았다.","SCMP는 화훙의 순이익이 147% 급증했다고 전했으며, 구체적인 증설 규모와 일정은 기사에 제시되지 않았다."],"url":"https://www.scmp.com/tech/big-tech/article/3373445/chinese-chipmaker-hua-hong-bets-big-silicon-photonics-amid-ai-boom","media":"SCMP","published_local":"2026-11-05 21:27 Hong_Kong","published_kst":"2026-11-05 22:27 KST","tickers":["688347.SS"],"names":["화훙반도체"],"sectors":["semi_chip"],"related":[],"as_of":"2026-11-05"},{"rank":10,"title":"램리서치(LRCX): 8-K - Current report","title_ko":"램리서치, 250억달러 자사주 매입 승인·분기 배당 주당 0.33달러","summary":["램리서치 이사회가 250억달러 규모의 자사주 매입 한도와 주당 0.33달러의 분기 배당을 승인했다.","이번 한도는 기존 승인 잔여분에 더해지며, 장내·장외 거래와 파생계약·구조화 매입 방식을 포함하고 종료 시한은 없다.","베팅어 CFO는 핵심 기술 전환점에서의 입지와 현금 창출력을 근거로 주주환원 목표를 달성할 수 있다고 밝혔다."],"url":"https://www.sec.gov/Archives/edgar/data/707549/000070754926000057/0000707549-26-000057-index.htm","media":"SEC EDGAR","published_local":"2026-11-05 16:17 New_York","published_kst":"2026-11-06 06:17 KST","tickers":["LRCX"],"names":["램리서치"],"sectors":["semi_equip"],"related":[],"as_of":"2026-11-05"}]};
